UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 주문을 시전할 때 움직이거나 제자리 뛰기를 하거나 ESC 키를 눌러 시전을 취소할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez annuler l\'incantation d\'un sort en vous déplaçant, en sautant ou en appuyant sur la touche d\'échappement.', `name_dede` = '|cffffd100Tipp:|r Das Wirken von Zaubern wird durch Bewegen, Springen oder Drücken der ESC-Taste unterbrochen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过移动、跳跃或Esc键来取消施法。', `name_zhtw` = '|cffffd100小提示:|r當你施展法術時可以藉由移動、跳躍或是按下ESC鍵取消。', `name_eses` = '|cffffd100Consejo:|r Para cancelar el lanzamiento de un hechizo, muévete, salta o pulsa la tecla <Esc>.|n|n', `name_esmx` = '|cffffd100Consejo:|r Para cancelar el lanzamiento de un hechizo, muévete, salta o pulsa la tecla <Esc>.|n|n', `name_ruru` = '|cffffd100Совет:|r Чтобы прервать заклинание, переместитесь, подпрыгните или нажмите клавишу Esc.' WHERE `id` = 201;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화창의 플레이어 이름을 마우스로 클릭하면 귓속말을 보낼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Cliquer sur le nom d\'un joueur dans la fenêtre de discussion vous permet de lui envoyer un message privé.', `name_dede` = '|cffffd100Tipp:|r Klickt Ihr im Chatfenster auf einen Spielernamen, könnt Ihr diesem Spieler eine private Nachricht senden.', `name_zhcn` = '|cffffd100小窍门：|r 在聊天窗口中点击玩家姓名可向对方发送悄悄话。', `name_zhtw` = '|cffffd100小提示:|r在對話視窗中點擊玩家名稱就可以傳送私人訊息給他們。', `name_eses` = '|cffffd100Consejo:|r Para enviar un mensaje privado a un jugador que has visto en la ventana de chat, haz clic sobre su nombre en esa ventana.|n', `name_esmx` = '|cffffd100Consejo:|r Para enviar un mensaje privado a un jugador que has visto en la ventana de chat, haz clic sobre su nombre en esa ventana.|n', `name_ruru` = '|cffffd100Совет:|r Щелкнув по имени игрока в окне чата, вы сможете отправить личное сообщение этому игроку.' WHERE `id` = 221;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 아이템을 CTRL 키를 누른 채로 클릭하면 착용한 모습을 미리 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez cliquer sur un objet tout en appuyant sur <Ctrl> pour voir quelle serait votre apparence si vous le portiez.', `name_dede` = '|cffffd100Tipp:|r Strg-klickt auf einen Ausrüstungsgegenstand im Spiel, um zu sehen wie dieser an Euch aussehen würde.', `name_zhcn` = '|cffffd100小窍门：|r 你可以按下Ctrl并点击物品查看该物品装备在自己身上的效果。', `name_zhtw` = '|cffffd100小提示:|r你可以按下Ctrl鍵並點擊一件物品來看看你穿上那件物品後的樣子。', `name_eses` = '|cffffd100Consejo:|r Si quieres ver qué aspecto tendrá tu personaje con un objeto, pulsa <Control> mientras haces clic sobre el objeto.|n', `name_esmx` = '|cffffd100Consejo:|r Si quieres ver qué aspecto tendrá tu personaje con un objeto, pulsa <Control> mientras haces clic sobre el objeto.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы посмотреть, как предмет будет смотреться на вашем персонаже, щелкните по этому предмету при нажатой клавише Ctrl.' WHERE `id` = 222;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 이름이 회색으로 표시되는 아이템은 품질이 낮은 아이템이며 일반적으로 상인에게 팔 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Un objet dont le nom apparaît en gris est de piètre qualité et peut le plus souvent être vendu sans regret à un marchand.', `name_dede` = '|cffffd100Tipp:|r Ein Gegenstand, dessen Name in grau angezeigt wird, ist von minderer Qualität und kann in den meisten Fällen bedenkenlos verkauft werden.', `name_zhcn` = '|cffffd100小窍门：|r 名称呈灰色的物品在游戏中一般没什么用处，可以出售给商人。', `name_zhtw` = '|cffffd100小提示:|r名字是灰色的物品一般來說表示粗糙的品質，你可以把它賣給商人。', `name_eses` = '|cffffd100Consejo:|r Los objetos con nombre en color gris son de baja calidad y en la mayoría de los casos se venden a los mercaderes.|n', `name_esmx` = '|cffffd100Consejo:|r Los objetos con nombre en color gris son de baja calidad y en la mayoría de los casos se venden a los mercaderes.|n', `name_ruru` = '|cffffd100Совет:|r Если название предмета написано серым цветом, значит, этот предмет низкого качества. Обычно такие вещи продают торговцам.' WHERE `id` = 223;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 이름이 흰색으로 표시되는 아이템은 쓸모가 있는 아이템이며 상인이나 경매장을 통해 팔 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Un objet dont le nom apparaît en blanc est utile aux joueurs d\'une certaine façon. Il peut être utilisé ou vendu à l\'hôtel des ventes.', `name_dede` = '|cffffd100Tipp:|r Ein Gegenstand, dessen Name in weiß angezeigt wird, erweist sich meistens auf irgendeine Weise als nützlich und kann entweder verwendet oder im Auktionshaus verkauft werden.', `name_zhcn` = '|cffffd100小窍门：|r 名称呈白色的物品在某些情况下有用，玩家可以使用这类物品或在拍卖所中进行出售。', `name_zhtw` = '|cffffd100小提示:|r名字為白色的物品一般來說對玩家是有用的，你可以將它拿到拍賣場去販售。', `name_eses` = '|cffffd100Consejo:|r Los objetos con nombre en color blanco son útiles para los personajes de alguna manera y se pueden usar o subastar.|n', `name_esmx` = '|cffffd100Consejo:|r Los objetos con nombre en color blanco son útiles para los personajes de alguna manera y se pueden usar o subastar.|n', `name_ruru` = '|cffffd100Совет:|r Если название предмета написано белым цветом, значит, он может быть полезен. Вы можете использовать этот предмет сами или выставить его на аукцион.' WHERE `id` = 224;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 게임 내에 있는 우체통을 이용하여 다른 플레이어나 자신의 다른 캐릭터에게 소포를 보낼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez envoyer du courrier aux autres joueurs ou même à vos autres personnages à partir de n\'importe quelle boîte aux lettres du jeu.', `name_dede` = '|cffffd100Tipp:|r Über die Briefkästen im Spiel könnt Ihr anderen Spielern und Euren Zweitcharakteren Post zusenden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用游戏中设立的邮箱向其他玩家或你的其他角色发送邮件。', `name_zhtw` = '|cffffd100小提示:|r你可以使用遊戲中任何一個郵箱來郵寄物品給其他玩家或者是你其他的角色。', `name_eses` = '|cffffd100Consejo:|r Puedes enviar mensajes de correo a otros jugadores o incluso a tus otros personajes desde cualquier buzón de correo del juego.|n', `name_esmx` = '|cffffd100Consejo:|r Puedes enviar mensajes de correo a otros jugadores o incluso a tus otros personajes desde cualquier buzón de correo del juego.|n', `name_ruru` = '|cffffd100Совет:|r В любом почтовом ящике можно оставить письмо для другого игрока или вашего альтернативного персонажа.' WHERE `id` = 225;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화창이 열려 있는 상태에서 SHIFT 키를 누른 채로 아이템을 클릭하면 대화창에 아이템 링크가 표시되어 다른 플레이어가 정보를 살펴볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez cliquer sur un objet tout en appuyant sur la touche Maj pour créer un lien vers cet objet dans la fenêtre de discussion.', `name_dede` = '|cffffd100Tipp:|r Shift-klickt auf einen Gegenstand, um diesen im Chatfenster zu verlinken.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在打开聊天对话框时按下Shift并点击物品，将物品链接到对话中供他人查看。', `name_zhtw` = '|cffffd100小提示:|r你可以按下Shift鍵並點擊某物品來放置一個物品連結於對話訊息中。', `name_eses` = '|cffffd100Consejo:|r Si deseas copiar un vínculo a un elemento en la ventana de chat, pulsa <Mayús> y haz clic sobre él.|n', `name_esmx` = '|cffffd100Consejo:|r Si deseas copiar un vínculo a un elemento en la ventana de chat, pulsa <Mayús> y haz clic sobre él.|n', `name_ruru` = '|cffffd100Совет:|r В сообщение можно вставить ссылку на какой-либо игровой предмет. Для этого щелкните по нужному предмету при нажатой клавише Shift.' WHERE `id` = 226;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 행동 단축바의 모든 아이콘은 주메뉴의 단축키 설정을 통하여 단축키를 변경할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les raccourcis de toutes vos barres d\'actions peuvent être reconfigurés dans l\'interface d\'association de touches.', `name_dede` = '|cffffd100Tipp:|r Die Tastaturkürzel für die Aktionsleiste können im Menü \'Tastaturbelegung\' neu festgelegt werden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在按键绑定界面中重新定义所有动作条对应的热键。', `name_zhtw` = '|cffffd100小提示:|r所有的快捷列按鈕都可以在快捷鍵設定介面中重新指定各自對應的熱鍵。', `name_eses` = '|cffffd100Consejo:|r Las teclas de acceso rápido de tus barras de acción se pueden redefinir desde la interfaz de Configurar teclado.|n', `name_esmx` = '|cffffd100Consejo:|r Las teclas de acceso rápido de tus barras de acción se pueden redefinir desde la interfaz de Configurar teclado.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете переназначить клавиши управления в меню назначения клавиш.' WHERE `id` = 227;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 캐릭터창의 평판란에서는 다른 여러 진영과의 관계를 확인할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Sur votre feuille de personnage se trouve un onglet de réputation qui vous indique votre statut auprès de différents groupes.', `name_dede` = '|cffffd100Tipp:|r Euer Charakterfenster verfügt über eine Seite \'Ruf\', auf welcher Ihr Euren Ruf bei den verschiedenen Fraktionen im Spiel überprüfen könnt.', `name_zhcn` = '|cffffd100小窍门：|r 角色信息框中的声望选项卡将显示你在各个阵营的声望数值。', `name_zhtw` = '|cffffd100小提示:|r在你的角色狀態表中有一個聲望的分頁，可以看出你跟不同勢力間的狀態。', `name_eses` = '|cffffd100Consejo:|r En tu panel de personaje verás una pestaña de reputación que te indica el estado que tienes con cada grupo.|n', `name_esmx` = '|cffffd100Consejo:|r En tu panel de personaje verás una pestaña de reputación que te indica el estado que tienes con cada grupo.|n', `name_ruru` = '|cffffd100Совет:|r В окне персонажа есть вкладка «Репутация». На ней показано, как к вам относятся различные фракции.' WHERE `id` = 229;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 감정 표현을 이용해서 다양한 재미있는 행동을 할 수 있습니다. 춤을 추려면 대화창에 /춤을 입력해 보세요.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez faire de nombreuses actions amusantes grâce au système des « emotes ». Par exemple, vous pouvez taper /danser pour danser.', `name_dede` = '|cffffd100Tipp:|r Emotes bieten Euch viele lustige Ausdrucksmöglichkeiten, z.B. kann Euer Charakter mit /tanzen einen 1a Moonwalk hinlegen. Grooovie.', `name_zhcn` = '|cffffd100小窍门：|r 你可以利用表情系统做出各种有趣的动作，例如键入/跳舞可以让你翩翩起舞。', `name_zhtw` = '|cffffd100小提示:|r你可以使用情感指令系統來表達許多有趣的動作，舉例來說你可以輸入/dance來跳舞。', `name_eses` = '|cffffd100Consejo:|r Con el sistema de emociones te lo puedes pasar en grande. ¡Prueba a escribir /bailar y verás bailar a tu personaje!|n', `name_esmx` = '|cffffd100Consejo:|r Con el sistema de emociones te lo puedes pasar en grande. ¡Prueba a escribir /bailar y verás bailar a tu personaje!|n', `name_ruru` = '|cffffd100Совет:|r В игре можно проявлять самые разные эмоции. Попробуйте, например, набрать команду /танец – и ваш персонаж примется танцевать.' WHERE `id` = 230;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r ESC 키를 눌러 나오는 게임 설정 메뉴에서는 게임에 관련된 다양한 설정을 변경할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Le menu Interface <Echap> vous propose de nombreux moyens de modifier à votre convenance votre expérience du jeu.', `name_dede` = '|cffffd100Tipp:|r Das Interfacemenü (ESC) bietet Euch zahlreiche Optionen zur freien Gestaltung Eures Gameplays.', `name_zhcn` = '|cffffd100小窍门：|r 你可以按下Esc调出界面选项菜单定制自己的游戏界面。', `name_zhtw` = '|cffffd100小提示:|r按下Esc鍵的介面選項中有很多可以調整遊戲進行方式的設定。', `name_eses` = '|cffffd100Consejo:|r El menú de opciones de la interfaz <Esc> tiene muchas opciones de configuración del juego.|n', `name_esmx` = '|cffffd100Consejo:|r El menú de opciones de la interfaz <Esc> tiene muchas opciones de configuración del juego.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы настроить игровой интерфейс по своему вкусу, нажмите клавишу Esc.' WHERE `id` = 231;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 설정 메뉴에서 퀘스트 내용 바로 표시 설정을 끌 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez activer le lent déroulement du texte des quêtes dans le menu Interface.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt das langsame Anzeigen von Questtexten im Interfacemenü aktivieren.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面选项菜单中切换任务文本逐渐显示的选项。', `name_zhtw` = '|cffffd100小提示:|r你可以在介面選項清單中將慢速捲動任務文字的選項關閉。', `name_eses` = '|cffffd100Consejo:|r Si deseas ver el texto de las misiones lentamente, puedes activar esta opción en el menú de opciones de la interfaz.|n|n', `name_esmx` = '|cffffd100Consejo:|r Si deseas ver el texto de las misiones lentamente, puedes activar esta opción en el menú de opciones de la interfaz.|n|n', `name_ruru` = '|cffffd100Совет:|r Вы можете включить медленное появление текста заданий в меню настройки интерфейса.' WHERE `id` = 232;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 특성을 선택할 때는 신중해야 합니다. 특성을 잘못 배워서 초기화하려면 많은 비용이 소요됩니다.', `name_frfr` = '|cffffd100Astuce :|r Réfléchissez bien avant d\'utiliser vos points de talent, car une fois vos talents choisis, il faut dépenser de l\'or pour les désapprendre.', `name_dede` = '|cffffd100Tipp:|r Wählt die Vergabe Eurer Talentpunkte mit Bedacht. Sind sie erst einmal vergeben, müsst Ihr zum Verlernen und Neuverteilen Gold ausgeben.', `name_zhcn` = '|cffffd100小窍门：|r 谨慎分配天赋点，你必须花钱来遗忘已分配的天赋。', `name_zhtw` = '|cffffd100小提示:|r小心使用你的天賦點數，一旦你使用之後，就必須花錢重新來忘卻天賦。', `name_eses` = '|cffffd100Consejo:|r Gasta tus puntos de talentos con cuidado, ya que cuando hayas seleccionado uno, si deseas olvidarlo, deberás pagar oro.|n', `name_esmx` = '|cffffd100Consejo:|r Gasta tus puntos de talentos con cuidado, ya que cuando hayas seleccionado uno, si deseas olvidarlo, deberás pagar oro.|n', `name_ruru` = '|cffffd100Совет:|r Расходуйте очки талантов с умом, так как за их возврат придется выложить круглую сумму.' WHERE `id` = 233;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 미니맵 가장자리에 표시되는 편지봉투 아이콘은 새로운 우편이 도착했다는 의미입니다. 가까운 우체통에서 확인해 보세요.', `name_frfr` = '|cffffd100Astuce :|r Une icône Courrier à côté de votre minicarte vous indique que vous avez un nouveau message. Rendez-vous à une boîte aux lettres pour le récupérer.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr neue Post erhalten habt, erscheint neben Eurer Minikarte ein Briefsymbol. Holt Eure Post am nächsten Briefkasten ab.', `name_zhcn` = '|cffffd100小窍门：|r 小地图旁的邮件图标表示你有新邮件。你可以在邮箱处收取新邮件。', `name_zhtw` = '|cffffd100小提示:|r在小地圖右上角出現郵件圖示表示你有新的郵件。去找一個郵箱來收取郵件。', `name_eses` = '|cffffd100Consejo:|r Si ves un icono de un sobre junto a tu minimapa, quiere decir que has recibido un correo nuevo. Ve hasta un buzón para recogerlo.|n', `name_esmx` = '|cffffd100Consejo:|r Si ves un icono de un sobre junto a tu minimapa, quiere decir que has recibido un correo nuevo. Ve hasta un buzón para recogerlo.|n', `name_ruru` = '|cffffd100Совет:|r Значок в виде конверта означает, что вам пришло письмо. Его можно получить в ближайшем почтовом ящике.' WHERE `id` = 234;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 화면에 표시된 행동 단축바가 부족하다면 인터페이스 설정 메뉴에서 추가 행동 단축바를 사용하도록 변경할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez ajouter des barres d\'actions supplémentaires à votre interface de jeu à partir du menu Interface.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt zusätzliche Aktionsleisten im Benutzerinterface einblenden. Die entsprechende Option befindet sich im Interfacemenü.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面选项窗口的游戏界面中添加额外的动作条。', `name_zhtw` = '|cffffd100小提示:|r你可以在介面選項中為你的遊戲介面增加額外的快捷列。', `name_eses` = '|cffffd100Consejo:|r Si lo deseas, puedes agregar barras de acción adicionales al juego desde el menú de opciones de la interfaz.|n', `name_esmx` = '|cffffd100Consejo:|r Si lo deseas, puedes agregar barras de acción adicionales al juego desde el menú de opciones de la interfaz.|n', `name_ruru` = '|cffffd100Совет:|r В меню настройки интерфейса на игровой экран можно добавить дополнительные панели команд.' WHERE `id` = 235;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전리품을 획득할 때 SHIFT 키를 누른 채로 대상을 오른쪽 클릭하면 대상의 모든 아이템을 자동으로 집을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous maintenez la touche Maj enfoncée tout en cliquant droit sur une cible pour prendre le butin, vous prendrez automatiquement tout le butin se trouvant sur la cible.', `name_dede` = '|cffffd100Tipp:|r Rechtsklickt bei gedrückter Shift-Taste auf ein Ziel, das Ihr plündern wollt, damit Ihr automatisch alle Gegenstände plündert.', `name_zhcn` = '|cffffd100小窍门：|r 如果你按下Shift并点击目标拾取物品，你将自动拾取目标上的所有物品。', `name_zhtw` = '|cffffd100小提示:|r如果你在搜括屍體的時候按住Shift鍵並以右鍵點擊拾取目標時，你就會自動撿取該屍體中所有的物品。', `name_eses` = '|cffffd100Consejo:|r Si mantienes la tecla <Mayús> pulsada mientras haces clic derecho sobre un objetivo que despojes, recogerás todo automáticamente.|n', `name_esmx` = '|cffffd100Consejo:|r Si mantienes la tecla <Mayús> pulsada mientras haces clic derecho sobre un objetivo que despojes, recogerás todo automáticamente.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы забрать всю добычу с поверженного противника, щелкните по нему правой кнопкой мыши при зажатой клавише Shift.' WHERE `id` = 236;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 같은 서버에서 마음에 맞는 친구를 만났다면 친구 목록을 열어 이름을 등록하세요.', `name_frfr` = '|cffffd100Astuce :|r Si vous avez aimé jouer avec quelqu\'un de votre royaume, ajoutez-le à votre liste d\'amis !', `name_dede` = '|cffffd100Tipp:|r Wenn es Euch Spaß gemacht hat, mit jemand Bestimmtem von Eurem Realm zusammen zu spielen, fügt ihn Eurer Freundesliste hinzu!', `name_zhcn` = '|cffffd100小窍门：|r 如果你想跟某个处于同一服务器的玩家一同游戏，请将他添加到你的好友列表中！', `name_zhtw` = '|cffffd100小提示:|r如果你覺得跟某人一起遊戲很有樂趣，把他們加到你的好友名單中吧!', `name_eses` = '|cffffd100Consejo:|r Si has disfrutado jugando con alguien de tu reino, añádelo a tu lista de amigos.|n', `name_esmx` = '|cffffd100Consejo:|r Si has disfrutado jugando con alguien de tu reino, añádelo a tu lista de amigos.|n', `name_ruru` = '|cffffd100Совет:|r Если вам понравилось играть с кем-нибудь из вашего игрового мира, вы можете добавить его в список друзей.' WHERE `id` = 237;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 파티 플레이 시 전리품 획득 설정에는 여러 가지가 있습니다. 파티장은 자신의 초상화를 오른쪽 클릭하여 전리품 획득 설정을 변경할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Il existe différentes possibilités de partage du butin lorsque vous êtes en groupe. Le chef du groupe peut cliquer-droit sur son propre portrait pour changer d\'option.', `name_dede` = '|cffffd100Tipp:|r Seid Ihr in einer Gruppe, könnt Ihr aus verschiedenen Plünderoptionen wählen. Um die aktuelle Einstellung anzupassen, muss der Gruppenanführer nur auf sein Portrait rechtsklicken.', `name_zhcn` = '|cffffd100小窍门：|r 组队时有多种拾取方式。队长可右键点击自己的头像更改拾取选项。', `name_zhtw` = '|cffffd100小提示:|r組隊時有多種不同的拾取選項。隊長可以在自己的頭像上點選右鍵來改變拾取方式。', `name_eses` = '|cffffd100Consejo:|r Existen numerosas opciones de botín para los grupos. El líder del grupo puede hacer clic derecho en su retrato para modificarlas.|n', `name_esmx` = '|cffffd100Consejo:|r Existen numerosas opciones de botín para los grupos. El líder del grupo puede hacer clic derecho en su retrato para modificarlas.|n', `name_ruru` = '|cffffd100Совет:|r Добычу между членами группы можно распределять по-разному. Лидер группы может изменить способ распределения добычи, щелкнув по своему портрету.' WHERE `id` = 239;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 특정 플레이어의 대화를 듣고 싶지 않다면 \'/차단\'을 사용할 수 있고, 또 언제든지 차단을 해제할 수도 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous ne voulez plus qu’un joueur vous parle, vous pouvez décider de le /ignorer. Vous pourrez toujours changer d’avis par la suite.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr von einem anderen Spieler nie wieder etwas hören möchtet, könnt Ihr ihn einfach /ignorieren. Ihr könnt Eure Meinung später auch wieder ändern.', `name_zhcn` = '|cffffd100小窍门：|r 如果你不再想收到某些玩家的任何消息，你可以使用/ignore命令来屏蔽他们。当然你也可以随时取消屏蔽。', `name_zhtw` = '|cffffd100小提示:|r如果你不想收到任何來自某位玩家的訊息，你可以對其使用/ignore(/忽略)。你也可以隨時變更忽略的狀態。', `name_eses` = '|cffffd100Consejo:|r Si no quieres volver a saber nada de otro jugador, puedes usar el comando /ignorar. Ya tendrás tiempo de cambiar de opinión después.', `name_esmx` = '|cffffd100Consejo:|r Si no quieres volver a saber nada de otro jugador, puedes usar el comando /ignorar. Ya tendrás tiempo de cambiar de opinión después.', `name_ruru` = '|cffffd100Совет:|r Если вы не хотите видеть сообщения от какого-то игрока, вы можете начать /игнорировать его. Позже вы можете передумать.' WHERE `id` = 240;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 단축키를 사용하여 파티원을 선택할 수 있습니다. F1 키는 자신, F2 키는 두 번째 파티원을 대상으로 선택합니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez cibler les membres de votre groupe à l\'aide des touches Fonction. F1 vous cible vous-même, F2 cible le deuxième membre du groupe.', `name_dede` = '|cffffd100Tipp:|r Mit den Funktionstasten könnt Ihr einzelne Mitglieder Eurer Gruppe anwählen. F1 wählt Euch an, F2 das zweite Gruppenmitglied und so weiter.', `name_zhcn` = '|cffffd100小窍门：|r 你可以利用功能键选定队伍成员。F1键选中自己；F2键选中第二个队伍成员，以此类推。', `name_zhtw` = '|cffffd100小提示:|r你可以使用功能鍵來選定自己的隊友作為目標。F1鍵可選定自己;F2鍵可選定第二個隊友。', `name_eses` = '|cffffd100Consejo:|r Para seleccionar a los miembros de tu grupo puedes pulsar las teclas de función: F1 para seleccionar a tu personaje, F2 al segundo miembro del grupo.|n', `name_esmx` = '|cffffd100Consejo:|r Para seleccionar a los miembros de tu grupo puedes pulsar las teclas de función: F1 para seleccionar a tu personaje, F2 al segundo miembro del grupo.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете выбирать игроков группы с помощью функциональных клавиш. Чтобы выбрать себя, нажмите F1, чтобы выбрать второго игрока из группы – F2.' WHERE `id` = 241;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 파티 플레이 시에는 예의를 꼭 지키세요.', `name_frfr` = '|cffffd100Astuce :|r Si vous êtes poli en groupe, vous aurez plus de chances d\'être invité à nouveau !', `name_dede` = '|cffffd100Tipp:|r Seid nett zu den anderen Gruppenmitgliedern, dann werdet Ihr auch wieder eingeladen.', `name_zhcn` = '|cffffd100小窍门：|r 组队时请保持礼貌，下次他们会再邀请你加入队伍的！', `name_zhtw` = '|cffffd100小提示:|r在一個隊伍中對其他人保持禮貌可以讓你持續受到邀請!', `name_eses` = '|cffffd100Consejo:|r Si eres cordial con los demás miembros de tu grupo, seguramente te volverán a invitar a jugar con ellos.', `name_esmx` = '|cffffd100Consejo:|r Si eres cordial con los demás miembros de tu grupo, seguramente te volverán a invitar a jugar con ellos.', `name_ruru` = '|cffffd100Совет:|r Будьте вежливы с товарищами по группе, и вас непременно пригласят в следующий раз!' WHERE `id` = 242;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 평판 창에서 각 진영 이름을 클릭하여 추가 정보를 확인하거나 해당 진영에 대한 설정을 할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Pour obtenir des informations supplémentaires sur une faction, cliquez sur son nom dans l’onglet de réputation.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt im Ruffenster auf eine Fraktion klicken, um zusätzliche Informationen und Optionen für diese Fraktion aufzurufen.', `name_zhcn` = '|cffffd100小窍门：|r 战场排队时你不需要守在战场门口。', `name_zhtw` = '|cffffd100小提示:|r你可以點擊聲望介面中的陣營以獲取更多關於該陣營的資訊與選項。', `name_eses` = '|cffffd100Consejo:|r Para obtener más información y ver las opciones de una facción, haz clic sobre ella en el panel de reputación.|n|n', `name_esmx` = '|cffffd100Consejo:|r Para obtener más información y ver las opciones de una facción, haz clic sobre ella en el panel de reputación.|n|n', `name_ruru` = '|cffffd100Совет:|r Во вкладке репутации записаны названия различных фракций. Щелкнув по названию фракции, вы получите дополнительные сведения о ней, а также сможете выполнить ряд других связанных с нею действий.' WHERE `id` = 243;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 초상화 주위에 은색용 모양이 둘러진 몬스터는 좀 더 좋은 전리품을 주는 희귀한 몬스터입니다.', `name_frfr` = '|cffffd100Astuce :|r Un monstre avec un dragon argenté autour de son portrait est un monstre rare qui détient un trésor de valeur supérieure à la moyenne.', `name_dede` = '|cffffd100Tipp:|r Gegner mit einem silbernen Drachen um ihr Portrait sind einzigartige Monster, die in der Regel höherwertige Beute bei sich tragen.', `name_zhcn` = '|cffffd100小窍门：|r 头像上带有银龙标识的怪物是稀有怪物，掉落的物品比一般怪物要好。', `name_zhtw` = '|cffffd100小提示:|r頭像旁帶有銀龍標誌的怪物是較為稀少的怪物，牠們身上通常會有比平常還好的物品。', `name_eses` = '|cffffd100Consejo:|r Si ves un monstruo cuyo retrato está rodeado por un dragón plateado, esto quiere decir que es poco común y que posee un tesoro mayor de lo normal.|n', `name_esmx` = '|cffffd100Consejo:|r Si ves un monstruo cuyo retrato está rodeado por un dragón plateado, esto quiere decir que es poco común y que posee un tesoro mayor de lo normal.|n', `name_ruru` = '|cffffd100Совет:|r Если портрет монстра украшен изображением серебряного дракона, это значит, что монстр редкий и добыча с него будет ценнее, чем обычно.' WHERE `id` = 244;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화창에 마우스 커서를 가져가면 대화창의 탭이 나타나고, 탭을 오른쪽 클릭하면 설정 창을 열 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous passez votre souris au-dessus d\'une fenêtre de discussion, elle devient visible et vous pouvez cliquer-droit sur l\'onglet de la fenêtre pour avoir accès à différentes options.', `name_dede` = '|cffffd100Tipp:|r Bewegt Ihr Eure Maus über ein Chatfenster, wird dieses sichtbar und kann für weitere Optionen rechtsgeklickt werden.', `name_zhcn` = '|cffffd100小窍门：|r 当鼠标移至聊天窗口的边框上时，边框将变为可见，你可以右键点击边框标签来更改设置。', `name_zhtw` = '|cffffd100小提示:|r當你將滑鼠移到對話視窗時，該視窗會變為可見，你可以在對話視窗的標籤上點選右鍵來看看有哪些選項。', `name_eses` = '|cffffd100Consejo:|r Si pasas el ratón por encima del panel de chat, este se volverá visible y podrás hacer clic derecho sobre él para ver las opciones.|n', `name_esmx` = '|cffffd100Consejo:|r Si pasas el ratón por encima del panel de chat, este se volverá visible y podrás hacer clic derecho sobre él para ver las opciones.|n', `name_ruru` = '|cffffd100Совет:|r Если вы наведете указатель мыши на окно чата, проступят его рамки. Щелкните правой кнопкой мыши по одной из вкладок окна, чтобы настроить его параметры.' WHERE `id` = 245;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 설정 메뉴에서 자신에게 걸린 이로운 마법효과의 지속시간을 표시하도록 설정할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez choisir d\'afficher la durée des améliorations dont vous bénéficiez dans le menu Interface.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Euch die verbleibende Wirkungsdauer von Stärkungszaubern über eine Option des Interfacemenüs anzeigen lassen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面选项菜单中显示作用在自己身上的增益法术的持续时间。', `name_zhtw` = '|cffffd100小提示:|r你可以在介面選項中設定開啟顯示增益法術的持續時間。', `name_eses` = '|cffffd100Consejo:|r En el menú de opciones de la interfaz hay una opción para ver la duración de los hechizos beneficiosos activos sobre ti.|n', `name_esmx` = '|cffffd100Consejo:|r En el menú de opciones de la interfaz hay una opción para ver la duración de los hechizos beneficiosos activos sobre ti.|n', `name_ruru` = '|cffffd100Совет:|r Благотворные заклинания действуют в течение определенного времени. Вы можете включить отображение этого времени в меню настройки интерфейса.' WHERE `id` = 246;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 행동 단축바를 잠그면 실수로 아이콘을 옮기는 것을 방지할 수 있습니다. 행동 단축바는 인터페이스 설정 메뉴에서 잠글 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Dans le menu Interface, vous pouvez verrouiller votre barre d\'actions afin d\'éviter de déplacer accidentellement des sorts.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Eure Aktionsleiste fixieren, damit Ihr Zauber nicht versehentlich verschiebt. Verwendet dazu die Interface-Optionen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面选项窗口中锁定动作条，避免不小心将法术图标从动作条中移除。', `name_zhtw` = '|cffffd100小提示:|r你可以在介面選項視窗中鎖定你的快捷列，這樣你就不會不小心移除法術。', `name_eses` = '|cffffd100Consejo:|r Puedes bloquear tu barra de acción para evitar mover hechizos por error. Esto se hace desde el menú de opciones de la interfaz.|n', `name_esmx` = '|cffffd100Consejo:|r Puedes bloquear tu barra de acción para evitar mover hechizos por error. Esto se hace desde el menú de opciones de la interfaz.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете зафиксировать панель команд, чтобы случайно не удалить заклинания. Это можно сделать в меню настройки интерфейса.' WHERE `id` = 247;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r ALT 키를 누른 채로 마법을 사용하면 현재 선택된 대상을 변경하지 않고도 자신에게 마법을 사용할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez lancer un sort sur vous-même sans désélectionner votre cible actuelle en maintenant enfoncée la touche <Alt> lorsque vous appuyez sur le raccourci.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Zauber auf Euch selbst wirken, ohne Euer derzeitiges Ziel abwählen zu müssen, indem Ihr die ALT-Taste gedrückt haltet und gleichzeitig den entsprechenden Zauber mittels Tastaturkürzel wirkt.', `name_zhcn` = '|cffffd100小窍门：|r 在不取消选定当前目标的情况下，你可以按下Alt并点击热键对自己施法。', `name_zhtw` = '|cffffd100小提示:|r你可以在不取消目前選定目標的狀態下，按下Alt鍵跟快捷鍵來對自己施展法術。', `name_eses` = '|cffffd100Consejo:|r Si deseas lanzar un hechizo sobre tu personaje, pero no deseas deseleccionar a tu objetivo actual, puedes hacerlo manteniendo la tecla <Alt> pulsada mientras pulsas tu tecla de acceso rápido.|n', `name_esmx` = '|cffffd100Consejo:|r Si deseas lanzar un hechizo sobre tu personaje, pero no deseas deseleccionar a tu objetivo actual, puedes hacerlo manteniendo la tecla <Alt> pulsada mientras pulsas tu tecla de acceso rápido.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете воздействовать заклинанием на себя, не отменяя при этом выбранной цели. Для этого нажмите Alt одновременно с нужной клавишей.' WHERE `id` = 248;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 경비병은 명예 점수를 주지 않습니다.', `name_frfr` = '|cffffd100Astuce :|r Tuer des gardes ne rapporte pas de points d\'honneur.', `name_dede` = '|cffffd100Tipp:|r Das Töten von Wachen wird nicht mit Ehrenpunkten belohnt.', `name_zhcn` = '|cffffd100小窍门：|r 杀死守卫不会获得任何荣誉。', `name_zhtw` = '|cffffd100小提示:|r殺死守衛無法得到榮譽點數。', `name_eses` = '|cffffd100Consejo:|r Matar a los guardias no te da honor.', `name_esmx` = '|cffffd100Consejo:|r Matar a los guardias no te da honor.', `name_ruru` = '|cffffd100Совет:|r За убийство стражей вы не получите очков чести.' WHERE `id` = 250;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r /매크로 명령을 이용하여 전투에 유용한 매크로를 만들 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous tapez /macro, vous ouvrez l\'interface permettant de créer des macros.', `name_dede` = '|cffffd100Tipp:|r Gebt /makro ein, um das Menü zum Erstellen von Makros aufzurufen.', `name_zhcn` = '|cffffd100小窍门：|r 键入 /宏 或者 /macro 可以调出宏制作界面。', `name_zhtw` = '|cffffd100小提示:|r輸入/macro會開啟建立巨集指令的介面。', `name_eses` = '|cffffd100Consejo:|r Escribe /macro para abrir la interfaz de creación de macros.|n', `name_esmx` = '|cffffd100Consejo:|r Escribe /macro para abrir la interfaz de creación de macros.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы создать макрос, введите команду /макро.' WHERE `id` = 251;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 이름이 회색으로 표시되는 레벨이 낮은 적 진영의 플레이어는 죽여도 명예 점수를 주지 않습니다.', `name_frfr` = '|cffffd100Astuce :|r Les personnages-joueurs ennemis dont le nom est affiché en gris sont d\'un niveau nettement inférieur au vôtre. Les tuer ne vous rapporte pas de points d\'honneur.', `name_dede` = '|cffffd100Tipp:|r Der Name gegnerischer Spieler, die weit unter der eigenen Stufe liegen, wird in grau angezeigt. Ihr erhaltet keine Ehre für das Töten dieser Gegner.', `name_zhcn` = '|cffffd100小窍门：|r 等级比你低很多的玩家名称呈灰色，杀死灰名的敌对玩家不会获得任何荣誉。', `name_zhtw` = '|cffffd100小提示:|r殺死等級遠低於你，名字顯示是灰色的敵對玩家無法得到榮譽點數。', `name_eses` = '|cffffd100Consejo:|r Los jugadores enemigos cuyo nombre te aparezca en gris tienen un nivel bastante inferior que el tuyo y no recibirás puntos de honor por matarlos.|n', `name_esmx` = '|cffffd100Consejo:|r Los jugadores enemigos cuyo nombre te aparezca en gris tienen un nivel bastante inferior que el tuyo y no recibirás puntos de honor por matarlos.|n', `name_ruru` = '|cffffd100Совет:|r Если имя игрока из враждебной фракции написано серым цветом, значит, этот игрок намного слабее вас. За его убийство вы не получите очков чести.' WHERE `id` = 252;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 공격대창에서 플레이어 이름을 마우스로 끌거나 직업 아이콘을 마우스로 끌어내면 생명력과 마나를 쉽게 확인할 수 있는 창이 표시됩니다.', `name_frfr` = '|cffffd100Astuce :|r Depuis l\'IU de raid, vous pouvez tirer le nom d\'un joueur vers le champ de jeu pour voir son statut ou tirer l\'icône d\'une classe pour voir tous les membres de cette classe.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt einen Spielernamen vom Schlachtzugsinterface auf das Spielfeld ziehen, damit dessen Status angezeigt wird, oder ein Charakterklassensymbol, um alle Mitglieder dieser Klasse zu sehen.', `name_zhcn` = '|cffffd100小窍门：|r 当你在团队中时，你可以从团队窗口中将某个小队或某种职业拖动到游戏画面，便于随时查看他们的生命值和法力值。', `name_zhtw` = '|cffffd100小提示:|r當你身在一個團隊時，你可以從團隊視窗中拖曳一個隊伍或是特定的職業到你的遊戲視窗中，這麼一來你就可以隨時注意他們的生命力及法力狀況。', `name_eses` = '|cffffd100Consejo:|r En la interfaz de banda puedes arrastrar a un jugador hasta el campo de juego para ver su estatus o arrastrar un icono de clase para ver a todos los miembros de esa clase.|n|n', `name_esmx` = '|cffffd100Consejo:|r En la interfaz de banda puedes arrastrar a un jugador hasta el campo de juego para ver su estatus o arrastrar un icono de clase para ver a todos los miembros de esa clase.|n|n', `name_ruru` = '|cffffd100Совет:|r Переместите имя игрока из окна рейда на основной экран, чтобы увидеть его статус. Переместив таким образом значок класса, вы получите сведения обо всех игроках этого класса, участвующих в рейде.' WHERE `id` = 253;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r ALT + Z 키를 누르면 인터페이스가 모두 사라져서 <Print Screen>을 눌러 멋진 스크린샷을 찍을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r <Alt>W vous permet de retirer et remettre votre interface pour faire des captures d\'écran avec <Impr écran>.', `name_dede` = '|cffffd100Tipp:|r Das Interface kann durch Drücken von ALT-Y ausgeblendet werden, um so schönere Screenshots mit Hilfe von <Druck> machen zu können.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在使用PrtScr截屏时按下Alt+Z键打开或关闭游戏操作界面。', `name_zhtw` = '|cffffd100小提示:|r按下Alt+Z鍵可以打開或關閉遊戲介面以便你使用PRINT SCREEN鍵擷取遊戲畫面。', `name_eses` = '|cffffd100Consejo:|r La interfaz se puede ocultar pulsando <Alt>Z. Para hacer una captura de pantalla pulsa <Impr Pant>.|n', `name_esmx` = '|cffffd100Consejo:|r La interfaz se puede ocultar pulsando <Alt>Z. Para hacer una captura de pantalla pulsa <Impr Pant>.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете убрать весь интерфейс, нажав Alt + Z, а затем сделать скриншот клавишей Print Screen.' WHERE `id` = 254;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자신이나 대상에게 걸린 강화 효과 및 약화 효과의 표시 여부를 설정하여 필요한 정보를 얻을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez définir quelles améliorations et affaiblissements afficher sur vous-même ou sur les autres joueurs pour obtenir les informations que vous souhaitez.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt auswählen, welche der auf Euch oder Ziele wirkenden Stärkungs- und Schwächugszauber angezeigt werden, damit Ihr die Informationen bekommt, die Ihr benötigt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以设置在自己和目标身上显示哪些增益法术和有害法术，来获得自己需要的信息。', `name_zhtw` = '|cffffd100小提示:|r你可以切換顯示在你或目標身上的增益或減益效果，以獲得你所需的資訊。', `name_eses` = '|cffffd100Consejo:|r Puedes seleccionar qué beneficios y perjuicios se muestran sobre ti o sobre los objetivos para obtener la información que necesitas.|n', `name_esmx` = '|cffffd100Consejo:|r Puedes seleccionar qué beneficios y perjuicios se muestran sobre ti o sobre los objetivos para obtener la información que necesitas.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете настроить отображение положительных и отрицательных эффектов на вашем персонаже и других целях, чтобы получать необходимую информацию.' WHERE `id` = 256;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화창의 플레이어 이름을 SHIFT 키를 누른 채로 마우스로 클릭하면 해당 플레이어의 정보를 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous cliquez sur le nom d\'un personnage-joueur dans la fenêtre de discussion tout en appuyant sur la touche Maj, des informations supplémentaires à son sujet apparaîtront.', `name_dede` = '|cffffd100Tipp:|r Durch Shift-klicken auf einen Spielernamen im Chatfenster, erhaltet Ihr zusätzliche Information zu diesem Spieler.', `name_zhcn` = '|cffffd100小窍门：|r 在聊天窗口中按下Shift并点击玩家名称，可显示关于该玩家的更多信息。', `name_zhtw` = '|cffffd100小提示:|r如果你按下Shift鍵並在對話欄中點擊一個玩家的姓名，就可以獲得該玩家的額外資訊。', `name_eses` = '|cffffd100Consejo:|r Si pulsas <Mayús> mientras haces clic sobre el nombre de un jugador en la ventana de chat, podrás ver información adicional.|n', `name_esmx` = '|cffffd100Consejo:|r Si pulsas <Mayús> mientras haces clic sobre el nombre de un jugador en la ventana de chat, podrás ver información adicional.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы получить дополнительные сведения об игроке, щелкните по его имени в окне чата при нажатой клавише Shift.' WHERE `id` = 258;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r NPC 위의 파란색 물음표는 반복할 수 있는 퀘스트를 준다는 것을 의미합니다.', `name_frfr` = '|cffffd100Astuce :|r Un point d\'interrogation bleu au-dessus d\'un donneur de quête indique que l\'on peut répéter la quête.', `name_dede` = '|cffffd100Tipp:|r Ein blaues Fragezeichen über einem Questgeber weist auf wiederholbare Quests hin.', `name_zhcn` = '|cffffd100小窍门：|r 任务给予者头上的蓝色问号表示该任务可重复完成。', `name_zhtw` = '|cffffd100小提示:|r當任務給予者的頭上有著藍色問號時表示這個任務是可重複進行的。', `name_eses` = '|cffffd100Consejo:|r Si ves un signo de interrogación azul sobre la cabeza de un asignador de misiones, significa que puedes repetir su misión.|n', `name_esmx` = '|cffffd100Consejo:|r Si ves un signo de interrogación azul sobre la cabeza de un asignador de misiones, significa que puedes repetir su misión.|n', `name_ruru` = '|cffffd100Совет:|r Если над персонажем, дающим задания, отображается синий вопросительный знак, это означает, что его задания можно выполнять по нескольку раз.' WHERE `id` = 261;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 다른 플레이어를 선택하고 있을 때 지원 단축키 <F>를 누르면 해당 플레이어가 선택한 대상을 선택할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Utilisez la touche de soutien (F) tout en ciblant un autre personnage-joueur et vous ciblerez le même adversaire que lui.', `name_dede` = '|cffffd100Tipp:|r Drückt den Button \'F\' (Ziel helfen), solange Ihr einen anderen Spieler angewählt habt, und Ihr visiert automatisch den gleichen Gegner wie dieser Spieler an.', `name_zhcn` = '|cffffd100小窍门：|r 在选定另一玩家的同时使用帮助按钮(F键)将自动锁定该玩家选定的怪物。', `name_zhtw` = '|cffffd100小提示:|r以其他玩家為目標時使用協助鍵(F鍵)，你選定的目標將會變成與該名玩家所選定的目標相同。', `name_eses` = '|cffffd100Consejo:|r Si deseas atacar al mismo objetivo que otro jugador, pulsa la tecla de asistencia (F) mientras tienes seleccionado al otro jugador.|n', `name_esmx` = '|cffffd100Consejo:|r Si deseas atacar al mismo objetivo que otro jugador, pulsa la tecla de asistencia (F) mientras tienes seleccionado al otro jugador.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы помочь другому игроку в бою, выберите его и нажмите клавишу F (А). Вашей целью станет его противник.' WHERE `id` = 262;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r TAB 키를 여러 번 눌러서 자신의 앞쪽에 있는 몬스터들을 번갈아 선택할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez utiliser la touche de tabulation pour sélectionner les ennemis proches se trouvant devant vous.', `name_dede` = '|cffffd100Tipp:|r Mit der TAB-Taste könnt Ihr nahegelegene Gegner anvisieren.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用Tab键选定你面前最近的敌人。', `name_zhtw` = '|cffffd100小提示:|r你可以使用TAB鍵來選擇在你前方最接近的敵人。', `name_eses` = '|cffffd100Consejo:|r Mediante el Tabulador puedes seleccionar a los enemigos más cercanos y a la vista.|n', `name_esmx` = '|cffffd100Consejo:|r Mediante el Tabulador puedes seleccionar a los enemigos más cercanos y a la vista.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете выбрать находящегося перед вами противника, нажав клавишу Tab. С помощью этой же клавиши вы можете переключаться между противниками, если их несколько.' WHERE `id` = 263;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 상인에게 물건을 팔 때 겹쳐진 아이템에 SHIFT 키를 누른 채로 마우스 왼쪽 버튼을 눌러 팔 수량을 결정할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous cliquez sur un objet vendu par un marchand tout en appuyant sur la touche Maj, vous pouvez choisir combien d\'exemplaires de cet objet vous souhaitez acheter.', `name_dede` = '|cffffd100Tipp:|r Shift-klickt im Verkaufsmenü eines Händlers auf einen Gegenstand, um die Anzahl der zu kaufenden Gegenstände festzulegen.', `name_zhcn` = '|cffffd100小窍门：|r 按住Shift再点击一件商人正在出售的物品可以指定你要购买的数量。', `name_zhtw` = '|cffffd100小提示:|r按住Shift鍵並點擊商人販售的物品可以讓你選擇購買商品的數量。', `name_eses` = '|cffffd100Consejo:|r Pulsa <Mayús> mientras haces clic sobre un objeto a la venta y podrás seleccionar la cantidad que deseas comprar.', `name_esmx` = '|cffffd100Consejo:|r Pulsa <Mayús> mientras haces clic sobre un objeto a la venta y podrás seleccionar la cantidad que deseas comprar.', `name_ruru` = '|cffffd100Совет:|r Чтобы купить у торговца несколько одинаковых предметов, нажмите Shift, а затем щелкните по необходимому предмету.' WHERE `id` = 281;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전문 기술이나 보조 기술을 배운 뒤에는 마법책 및 능력창을 열고 일반 항목에서 해당 기술을 선택하여 사용할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Lorsque vous apprenez un métier ou une compétence secondaire, le bouton qui vous permet d\'exécuter cette compétence se trouve dans l\'onglet général de votre grimoire.', `name_dede` = '|cffffd100Tipp:|r Erlernt Ihr einen Beruf oder eine sekundäre Fertigkeit, so findet Ihr das zugehörige Aktionssymbol im Bereich \'Allgemein\' Eures Zauberbuchs.', `name_zhcn` = '|cffffd100小窍门：|r 当你学习了一项专业或辅助技能后，该技能的图标会出现在你的法术书中。', `name_zhtw` = '|cffffd100小提示:|r當你學會一項專業技能或是次要技能時，你可以在你的法術書中的綜合類分頁中找到使用該技能的按鈕。', `name_eses` = '|cffffd100Consejo:|r Cuando aprendes una profesión o una habilidad secundaria, el botón de acción para llevarla a cabo se encuentra en la pestaña general de tu libro de hechizos.', `name_esmx` = '|cffffd100Consejo:|r Cuando aprendes una profesión o una habilidad secundaria, el botón de acción para llevarla a cabo se encuentra en la pestaña general de tu libro de hechizos.', `name_ruru` = '|cffffd100Совет:|r Когда вы осваиваете профессиональные и вспомогательные навыки, в книге заклинаний появляются соответствующие значки.' WHERE `id` = 282;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대도시의 경비병에게 말을 걸면 여러 장소들의 길안내를 받을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous avez des difficultés à trouver quelque chose dans une capitale, demandez à un garde de vous indiquer votre chemin.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr innerhalb einer Stadt nach einem bestimmten Ort sucht, können Euch die Stadtwachen den Weg weisen.', `name_zhcn` = '|cffffd100小窍门：|r 如果你在主城中迷失了方向，可以向卫兵询问。', `name_zhtw` = '|cffffd100小提示:|r如果你在各主城中找不到某個人時，試著去跟守衛詢問一下方向。', `name_eses` = '|cffffd100Consejo:|r Si no logras encontrar algo en una capital, prueba a preguntar a los guardias.|n', `name_esmx` = '|cffffd100Consejo:|r Si no logras encontrar algo en una capital, prueba a preguntar a los guardias.|n', `name_ruru` = '|cffffd100Совет:|r Если вы заблудились в крупном городе, попробуйте спросить дорогу у стража.' WHERE `id` = 321;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 모든 것은 적당히 즐기시는 것이 좋습니다. (그게 월드 오브 워크래프트라도 말이죠!)', `name_frfr` = '|cffffd100Astuce :|r Souvenez-vous que tout doit être apprécié avec modération (même World of Warcraft !)', `name_dede` = '|cffffd100Tipp:|r Man sollte alles in Maßen genießen (sogar World of Warcraft)!', `name_zhcn` = '|cffffd100小窍门：|r 请记住，无论做什么都要适度（包括魔兽世界）！', `name_zhtw` = '|cffffd100小提示:|r記得溫和的對待所有事物(即使在魔獸世界也一樣!)', `name_eses` = '|cffffd100Consejo:|r Recuerda que tienes que ser moderado con todo (¡incluso con World of Warcraft!).', `name_esmx` = '|cffffd100Consejo:|r Recuerda que tienes que ser moderado con todo (¡incluso con World of Warcraft!).', `name_ruru` = '|cffffd100Совет:|r Не забывайте, что все хорошо в меру (даже World of Warcraft)!' WHERE `id` = 341;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r대화창에서 <Alt>와 위, 아래 화살표키를 눌러 이전에 보낸 메시지를 다시 선택할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez revoir les messages que vous aviez envoyés précédemment dans la fenêtre de discussion en appuyant sur <Alt> et la touche flèche vers le haut.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt zuvor im Chat gesendete Nachrichten lesen, indem Ihr <Alt> und die obere Pfeiltaste drückt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以按住<Alt>和上键查看你以前发送的各条消息。', `name_zhtw` = '|cffffd100小提示:|r你可以按下Alt+↑鍵來瀏覽你先前傳送出去的對話。', `name_eses` = '|cffffd100Consejo:|r Si deseas ver los mensajes de chat anteriores, pulsa <Alt> y las teclas de dirección arriba y abajo.', `name_esmx` = '|cffffd100Consejo:|r Si deseas ver los mensajes de chat anteriores, pulsa <Alt> y las teclas de dirección arriba y abajo.', `name_ruru` = '|cffffd100Совет:|r Чтобы просмотреть отправленные ранее сообщения, нажмите Alt и клавишу со стрелкой вверх одновременно.' WHERE `id` = 380;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 겹쳐지는 아이템을 <Shift> 마우스 왼쪽 클릭을 하여 수량을 나눌 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Cliquez sur une pile d’objets en appuyant sur la touche Maj pour la scinder en piles plus petites.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt gestapelte Gegenstände Shift-klicken, um sie aufzuteilen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用Shift+点击来把堆叠起来的物品分成几摞。', `name_zhtw` = '|cffffd100小提示:|r你可以按住Shift鍵點擊堆疊的物品來將它們分成更小的堆疊。', `name_eses` = '|cffffd100Consejo:|r Con la tecla <Mayús> pulsada, haz clic en una pila de objetos para repartirlos en pilas de menor tamaño.', `name_esmx` = '|cffffd100Consejo:|r Con la tecla <Mayús> pulsada, haz clic en una pila de objetos para repartirlos en pilas de menor tamaño.', `name_ruru` = '|cffffd100Совет:|r Чтобы разделить одинаковые предметы в одной ячейке, щелкните по ним при нажатой клавише Shift.' WHERE `id` = 381;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 마우스의 왼쪽 버튼과 오른쪽 버튼을 동시에 누르면 캐릭터가 앞으로 이동합니다.', `name_frfr` = '|cffffd100Astuce :|r Appuyez simultanément sur les deux boutons de la souris pour faire courir votre personnage.', `name_dede` = '|cffffd100Tipp:|r Euer Charakter rennt, wenn Ihr beide Maustasten gleichzeitig gedrückt haltet.', `name_zhcn` = '|cffffd100小窍门：|r 同时按下鼠标左右键，你的角色就会奔跑起来。', `name_zhtw` = '|cffffd100小提示:|r同時按住滑鼠的兩個鍵可以讓你的角色奔跑。', `name_eses` = '|cffffd100Consejo:|r Si pulsas los dos botones del ratón a la vez, harás correr a tu personaje.', `name_esmx` = '|cffffd100Consejo:|r Si pulsas los dos botones del ratón a la vez, harás correr a tu personaje.', `name_ruru` = '|cffffd100Совет:|r Зажмите обе кнопки мыши одновременно, чтобы ваш персонаж побежал.' WHERE `id` = 382;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 플레이어의 귓속말에 답장을 보낼 때 (키보드 R) TAB키를 누르면 최근에 답장을 보낸 플레이어 중에서 귓속말을 보낼 사람을 선택할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Quand vous répondez à un message (touche par défaut « R »), vous pouvez sélectionner avec la touche <TAB> parmi les personnages à qui vous avez répondu récemment.', `name_dede` = '|cffffd100Tipp:|r Antwortet man einem Spieler mit Hilfe der R-Taste (Standardeinstellung), kann man mit Hilfe der Taste <TAB> nacheinander die zuletzt angesprochenen Spieler auswählen.', `name_zhcn` = '|cffffd100小窍门：|r 当你要回复一个向你发送悄悄话的玩家（默认按键是\'R\'）时，使用<TAB>键可以在多名你最近回复过的玩家之间切换。', `name_zhtw` = '|cffffd100小提示:|r當你回覆玩家的「告訴」訊息時(原定R鍵)，Tab鍵可以逐一切換你最近回覆過的玩家。', `name_eses` = '|cffffd100Consejo:|r Con el Tabulador puedes ir cambiando entre los distintos jugadores a los que has respondido mediante mensajes privados (por defecto, con la tecla R).', `name_esmx` = '|cffffd100Consejo:|r Con el Tabulador puedes ir cambiando entre los distintos jugadores a los que has respondido mediante mensajes privados (por defecto, con la tecla R).', `name_ruru` = '|cffffd100Совет:|r Отвечая на реплику игрока (по умолчанию с помощью R), вы можете переключаться на имена пользователей, которым недавно отвечали, с помощью клавиши Tab.' WHERE `id` = 383;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자신에게 도움이 되는 마법 효과는 아이콘을 마우스 오른쪽 버튼으로 클릭하여 해제할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez annuler une amélioration amicale sur vous-même par un clic droit sur l’icône de l\'effet du sort.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt einen positiven Stärkungszauber von Euch nehmen, indem Ihr auf das entsprechende Stärkungszaubersymbol rechtsklickt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过右键点击一个施加在自己身上的增益效果图标来取消该效果。', `name_zhtw` = '|cffffd100小提示:|r你可以用右鍵點擊法術效果的圖示來解除自己身上的友善強化法術。', `name_eses` = '|cffffd100Consejo:|r Si haces clic derecho sobre una ventaja que le han dado a tu personaje, podrás desactivarla.', `name_esmx` = '|cffffd100Consejo:|r Si haces clic derecho sobre una ventaja que le han dado a tu personaje, podrás desactivarla.', `name_ruru` = '|cffffd100Совет:|r Чтобы отменить действующее на вас благотворное заклинание, щелкните по его значку правой кнопкой мыши.' WHERE `id` = 384;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 블리자드 직원은 절대 여러분의 비밀번호를 물어보지 않습니다.', `name_frfr` = '|cffffd100Astuce :|r Un employé de Blizzard ne vous demandera JAMAIS votre mot de passe.', `name_dede` = '|cffffd100Tipp:|r Mitarbeiter von Blizzard werden Euch NIEMALS nach Eurem Passwort fragen.', `name_zhcn` = '|cffffd100小窍门：|r 网易和暴雪娱乐的雇员**绝对**不会询问你的密码。', `name_zhtw` = '|cffffd100小提示:|rBlizzard員工絕對不會向你詢問你的帳號密碼。', `name_eses` = '|cffffd100Consejo:|r NINGÚN empleado de Blizzard JAMÁS te pedirá tu contraseña.', `name_esmx` = '|cffffd100Consejo:|r NINGÚN empleado de Blizzard JAMÁS te pedirá tu contraseña.', `name_ruru` = '|cffffd100Совет:|r Сотрудники компании Blizzard НИКОГДА не попросят вас сообщить ваш пароль.' WHERE `id` = 387;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화 창에서 괄호로 둘러싸인 아이템 이름을 클릭하면 아이템의 자세한 정보를 살펴볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Cliquez sur un nom d’objet entre crochets dans la fenêtre de discussion pour obtenir plus de détails sur cet objet.', `name_dede` = '|cffffd100Tipp:|r Klickt man im Chat auf einen in eckigen Klammern stehenden Namen eines Gegenstands, erhält man weitere Informationen darüber.', `name_zhcn` = '|cffffd100小窍门：|r 点击在聊天频道中链接出来的物品名就可以查看它的详细信息。', `name_zhtw` = '|cffffd100小提示:|r點擊對話中被括弧起來的物品名稱可以讓你更了解該物品。', `name_eses` = '|cffffd100Consejo:|r Si haces clic sobre el nombre de un objeto que aparece entre corchetes en la ventana de chat, verás más información sobre él.|n', `name_esmx` = '|cffffd100Consejo:|r Si haces clic sobre el nombre de un objeto que aparece entre corchetes en la ventana de chat, verás más información sobre él.|n', `name_ruru` = '|cffffd100Совет:|r Названия некоторых предметов в окне чата выделены квадратными скобками. Щелкнув по такому названию, вы получите дополнительные сведения о предмете.' WHERE `id` = 388;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전문 기술은 최대 2개까지 배울 수 있지만, 낚시나 요리, 응급치료와 같은 보조 기술은 개수에 제한 없이 배울 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous ne pouvez pas exercer plus de deux professions à la fois, mais vous pouvez apprendre toutes les compétences secondaires (pêche, cuisine et secourisme).', `name_dede` = '|cffffd100Tipp:|r Ihr könnt immer nur zwei Berufe gleichzeitig ausüben, jedoch alle sekundären Fertigkeiten (Angeln, Kochen und Erste Hilfe) beherrschen.', `name_zhcn` = '|cffffd100小窍门：|r 你只能学习两种专业技能，但可以学习所有辅助技能（包括钓鱼，烹饪和急救）。', `name_zhtw` = '|cffffd100小提示:|r你一次只能學習兩種專業技能，但你可以學習所有的次要技能(釣魚、烹飪和急救)。', `name_eses` = '|cffffd100Consejo:|r Solo puedes aprender dos profesiones al mismo tiempo, pero también es posible aprender todas las habilidades secundarias (pesca, cocina y primeros auxilios).', `name_esmx` = '|cffffd100Consejo:|r Solo puedes aprender dos profesiones al mismo tiempo, pero también es posible aprender todas las habilidades secundarias (pesca, cocina y primeros auxilios).', `name_ruru` = '|cffffd100Совет:|r Вы можете владеть только двумя профессиями, зато вам доступны все вспомогательные навыки (рыбная ловля, кулинария, верховая езда, оказание первой помощи).' WHERE `id` = 389;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 파티에 초대하거나 거래를 요청하기 전에 먼저 상대방의 의사를 물어보는 것이 좋습니다.', `name_frfr` = '|cffffd100Astuce :|r Il est bien vu de parler à quelqu’un avant de l’inviter dans un groupe ou d’ouvrir une fenêtre d’échange.', `name_dede` = '|cffffd100Tipp:|r Bevor man einen Spieler in eine Gruppe einlädt oder ihm einen Handel anbietet, sollte man zunächst ein paar Worte gewechselt haben.', `name_zhcn` = '|cffffd100小窍门：|r 在邀请某人加入小队或进行交易之前，最好先出于礼貌询问一下对方是否愿意如此。', `name_zhtw` = '|cffffd100小提示:|r在邀請某人加入一個隊伍或開啟交易視窗前，先和他交談是有禮貌的行為。', `name_eses` = '|cffffd100Consejo:|r Antes de invitar a alguien a un grupo o abrir una ventana de comercio, es recomendable que hables con la persona.', `name_esmx` = '|cffffd100Consejo:|r Antes de invitar a alguien a un grupo o abrir una ventana de comercio, es recomendable que hables con la persona.', `name_ruru` = '|cffffd100Совет:|r Прежде чем приглашать игрока в группу или предлагать ему сделку, проявите учтивость и спросите, не против ли он.' WHERE `id` = 390;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 적 진영의 플레이어에게 죽었을 경우엔 아이템의 내구도가 감소되지 않습니다.', `name_frfr` = '|cffffd100Astuce :|r Vos objets ne subissent pas de dégâts de durabilité si vous vous faites tuer par un personnage-joueur de la faction adverse.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr von anderen Spielern getötet werdet, erleidet Eure Ausrüstung keinen Haltbarkeitsschaden.', `name_zhcn` = '|cffffd100小窍门：|r 当你被敌对玩家杀死时，你的物品不会遭受任何耐久度损失。', `name_zhtw` = '|cffffd100小提示:|r當你被敵方玩家殺死時你的物品不會受到耐久度的損害。', `name_eses` = '|cffffd100Consejo:|r Tus objetos no pierden durabilidad si te mata un jugador enemigo.', `name_esmx` = '|cffffd100Consejo:|r Tus objetos no pierden durabilidad si te mata un jugador enemigo.', `name_ruru` = '|cffffd100Совет:|r Если вашего персонажа убьет игрок из враждебной фракции, прочность ваших предметов не уменьшится.' WHERE `id` = 392;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 퀘스트 목록에서 퀘스트 제목에 <Shift> 왼쪽 클릭을 하면 화면에 퀘스트 알림 내용이 표시되어 쉽게 상황을 살펴볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Cliquez sur une quête dans votre journal en appuyant sur la touche <Maj> pour afficher le suivi de cette quête.', `name_dede` = '|cffffd100Tipp:|r Shift-klickt in Eurem Questlog auf eine Quest, um die Questzielübersicht ein- und auszuschalten.', `name_zhcn` = '|cffffd100小窍门：|r 按住<Shift>并点击任务列表中的任务名，就可以追踪该任务的进展。', `name_zhtw` = '|cffffd100小提示:|r按下Shift鍵點擊任務記錄中的任務可以切換其任務追蹤的功能。', `name_eses` = '|cffffd100Consejo:|r Pulsa <Mayús> y haz clic sobre una misión en el registro de misiones para activar el seguimiento de lo que tienes que hacer en esa misión.|n', `name_esmx` = '|cffffd100Consejo:|r Pulsa <Mayús> y haz clic sobre una misión en el registro de misiones para activar el seguimiento de lo que tienes que hacer en esa misión.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы отслеживать выполнение задания, щелкните по его названию в журнале при нажатой клавише Shift.' WHERE `id` = 393;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 퀘스트를 완료할 수 있는 NPC가 근처에 있다면 미니맵에 노란색 물음표로 표시됩니다.', `name_frfr` = '|cffffd100Astuce :|r Les donneurs de quête proches qui attendent votre retour sont indiqués par des points d\'interrogation jaunes sur votre minicarte.', `name_dede` = '|cffffd100Tipp:|r In der Nähe befindliche Questgeber, die auf Eure Rückkehr warten, werden auf der Minikarte als gelbe Fragezeichen angezeigt.', `name_zhcn` = '|cffffd100小窍门：|r 在附近等待你交还任务的NPC会以金色问号的形式显示在你的微缩地图上。', `name_zhtw` = '|cffffd100小提示:|r在附近等待你回報的任務給予者會在你的小地圖上顯示黃色問號的圖示。', `name_eses` = '|cffffd100Consejo:|r Los personajes con misión cercanos que estén esperando que regreses tras acabar una se muestran en el minimapa como un símbolo de interrogación amarillo.|n', `name_esmx` = '|cffffd100Consejo:|r Los personajes con misión cercanos que estén esperando que regreses tras acabar una se muestran en el minimapa como un símbolo de interrogación amarillo.|n', `name_ruru` = '|cffffd100Совет:|r Местонахождение ближайших персонажей, которые дали вам задание и теперь ждут вашего возвращения, отображается на миникарте желтыми вопросительными знаками.' WHERE `id` = 394;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 퀘스트를 완료할 수 있는 NPC가 근처에 있다면 미니맵에 물음표로 표시됩니다.', `name_frfr` = '|cffffd100Astuce :|r Les donneurs de quête proches qui attendent votre retour sont indiqués par un point d\'interrogation sur votre minicarte.', `name_dede` = '|cffffd100Tipp:|r In der Nähe befindliche Questgeber, die auf Eure Rückkehr warten, werden auf der Minikarte als Fragezeichen angezeigt.', `name_zhcn` = '|cffffd100小窍门：|r 在附近等待你交还任务的NPC会以小问号的形式显示在你的微缩地图上。', `name_zhtw` = '|cffffd100小提示:|r在附近等你回報的任務NPC會在你的小地圖上顯示問號的圖示。', `name_eses` = '|cffffd100Consejo:|r Los personajes con misión cercanos que estén esperando que regreses se muestran en el minimapa como una interrogación.|n', `name_esmx` = '|cffffd100Consejo:|r Los personajes con misión cercanos que estén esperando que regreses se muestran en el minimapa como una interrogación.|n', `name_ruru` = '|cffffd100Совет:|r Вопросительными знаками на миникарте обозначаются ближайшие персонажи, которые дали вам задание и теперь ждут вашего возвращения.' WHERE `id` = 396;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 각 진영의 대도시 경매장은 서로 연결되어 있어 어디서라도 같은 목록이 나타납니다.', `name_frfr` = '|cffffd100Astuce :|r Les hôtels des ventes de chacune des villes principales de votre faction sont liés.', `name_dede` = '|cffffd100Tipp:|r Die Auktionshäuser in den Hauptstädten Eurer Fraktionen sind miteinander verknüpft.', `name_zhcn` = '|cffffd100小窍门：|r 你所在阵营的每座主城中都有拍卖行，而且它们是互相连通的。', `name_zhtw` = '|cffffd100小提示:|r同陣營主城裡的所有拍賣場都是聯結在一起的。', `name_eses` = '|cffffd100Consejo:|r Las casas de subastas de las ciudades principales de tu facción están conectadas unas con otras.|n', `name_esmx` = '|cffffd100Consejo:|r Las casas de subastas de las ciudades principales de tu facción están conectadas unas con otras.|n', `name_ruru` = '|cffffd100Совет:|r Аукционы в крупнейших городах вашей фракции связаны между собой.' WHERE `id` = 397;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 호위 퀘스트를 시작하기 전에 파티원이 모두 해당 퀘스트를 수행할 준비가 되어 있는지 확인하시기 바랍니다.', `name_frfr` = '|cffffd100Astuce :|r Assurez-vous que tous les membres du groupe en sont à la même étape d’une quête d’escorte avant de déclencher la quête.', `name_dede` = '|cffffd100Tipp:|r Bevor Ihr eine Begleitquest startet, stellt sicher, dass alle Eure Gruppenmitglieder auf dem gleichen Stand der Quest sind.', `name_zhcn` = '|cffffd100小窍门：|r 在启动一个护送类的任务之前，请确认所有的队友都在附近。', `name_zhtw` = '|cffffd100小提示:|r在開始一個護送任務前先確認所有的小隊成員都在一樣的階段。', `name_eses` = '|cffffd100Consejo:|r Asegúrate de que todos los miembros de tu grupo estén en la misma etapa de una misión de escolta antes de comenzarla.', `name_esmx` = '|cffffd100Consejo:|r Asegúrate de que todos los miembros de tu grupo estén en la misma etapa de una misión de escolta antes de comenzarla.', `name_ruru` = '|cffffd100Совет:|r Прежде чем приступить к выполнению задания по сопровождению кого-либо, убедитесь, что все члены группы находятся на одном и том же этапе задания.' WHERE `id` = 398;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 최고 레벨에 도달했을 때 퀘스트를 완료하면 경험치 대신 돈으로 보상을 받게 됩니다.', `name_frfr` = '|cffffd100Astuce :|r Les quêtes que vous accomplissez quand vous êtes au niveau maximum vous rapportent de l’argent à la place de l’expérience.', `name_dede` = '|cffffd100Tipp:|r Quests, die nach Erreichen der Maximalstufe abgeschlossen werden, gewähren Gold anstelle von Erfahrung.', `name_zhcn` = '|cffffd100小窍门：|r 如果你在满级之后完成任务，你所得到的经验值奖励会被换算为金币。', `name_zhtw` = '|cffffd100小提示:|r在最高等級時完成任務將以金錢代替經驗值做為獎勵。', `name_eses` = '|cffffd100Consejo:|r Las misiones completadas con el nivel máximo dan dinero en lugar de experiencia.|n', `name_esmx` = '|cffffd100Consejo:|r Las misiones completadas con el nivel máximo dan dinero en lugar de experiencia.|n', `name_ruru` = '|cffffd100Совет:|r Достигнув максимального уровня, за выполнение заданий вы будете получать не опыт, а деньги.' WHERE `id` = 399;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 낚시가 번번이 실패한다면 낚싯대에 미끼를 사용해 보시기 바랍니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous avez des difficultés pour pêcher dans une zone, essayez de mettre un appât sur votre canne à pêche.', `name_dede` = '|cffffd100Tipp:|r Solltet Ihr in gewissen Gebieten kein Glück beim Angeln haben, versucht einmal, einen Köder an Eurer Angelrute zu befestigen.', `name_zhcn` = '|cffffd100小窍门：|r 如果你在某个地区很难钓到鱼，请尝试在鱼竿上附加鱼饵。', `name_zhtw` = '|cffffd100小提示:|r如果你不能在某區域內釣魚，試著在你的釣魚竿加上一個誘餌。', `name_eses` = '|cffffd100Consejo:|r Si tienes problemas para pescar en una zona, inténtalo colocando una carnada en tu caña de pescar.', `name_esmx` = '|cffffd100Consejo:|r Si tienes problemas para pescar en una zona, inténtalo colocando una carnada en tu caña de pescar.', `name_ruru` = '|cffffd100Совет:|r Если рыба не клюет, попробуйте насадить на крючок приманку.' WHERE `id` = 400;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 음식과 음료는 동시에 먹을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Votre personnage peut manger et boire simultanément.', `name_dede` = '|cffffd100Tipp:|r Euer Charakter kann gleichzeitig essen und trinken.', `name_zhcn` = '|cffffd100小窍门：|r 你的角色可以同时进食和饮水。', `name_zhtw` = '|cffffd100小提示:|r你的角色可以同時進食及飲水。', `name_eses` = '|cffffd100Consejo:|r Tu personaje puede comer y beber al mismo tiempo.', `name_esmx` = '|cffffd100Consejo:|r Tu personaje puede comer y beber al mismo tiempo.', `name_ruru` = '|cffffd100Совет:|r Ваш персонаж может есть и пить одновременно.' WHERE `id` = 401;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 지정된 전장 주간에 전장에 참여하면 평소보다 명예 점수를 많이 올릴 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Participer à une bataille pendant la période d’appel aux armes du champ de bataille concerné augmente les gains d’honneur.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr an einem Wochenende, an dem sich die Botschafter eines Schlachtfeldes in den Hauptstädten befinden, auf diesem Schlachtfeld spielt, erhaltet Ihr dort mehr Ruf- und Ehrenpunkte.', `name_zhcn` = '|cffffd100小窍门：|r 在每个战场节日期间进入相应的战场，你所获得的荣誉会提高。', `name_zhtw` = '|cffffd100小提示:|r在假日週末進入戰場會提高你獲得的聲望值及榮譽點數。', `name_eses` = '|cffffd100Consejo:|r Si juegas en un campo de batalla durante su fin de semana especial, ganarás más puntos de honor.|n', `name_esmx` = '|cffffd100Consejo:|r Si juegas en un campo de batalla durante su fin de semana especial, ganarás más puntos de honor.|n', `name_ruru` = '|cffffd100Совет:|r Вы получите больше очков чести, сражаясь именно на том поле боя, которому посвящены текущие выходные.' WHERE `id` = 402;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r <Shift + B> 키를 누르면 가방을 한번에 열 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Appuyez sur <Maj>-B pour ouvrir tous vos sacs d’un coup.', `name_dede` = '|cffffd100Tipp:|r Um alle Taschen gleichzeitig zu öffnen, drückt <Shift>-B.', `name_zhcn` = '|cffffd100小窍门：|r <Shift>-B可以一次打开所有背包。', `name_zhtw` = '|cffffd100小提示:|r按下Shift+B鍵可以一次打開所有的背包。', `name_eses` = '|cffffd100Consejo:|r Si pulsas <Mayús> B, abrirás todas las bolsas al mismo tiempo.', `name_esmx` = '|cffffd100Consejo:|r Si pulsas <Mayús> B, abrirás todas las bolsas al mismo tiempo.', `name_ruru` = '|cffffd100Совет:|r Чтобы открыть все сумки одновременно, нажмите Shift + B.' WHERE `id` = 403;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 플레이어에게 친절하게 대한다면 오래도록 함께할 동료를 얻게될 것입니다.', `name_frfr` = '|cffffd100Astuce :|r Lors de vos interactions avec d’autres personnages, souvenez-vous qu’un minimum de courtoisie peut ouvrir bien des portes !', `name_dede` = '|cffffd100Tipp:|r Seid nett zu anderen Spielern, dann sind sie es auch zu Euch.', `name_zhcn` = '|cffffd100小窍门：|r 当你和其他玩家一起游戏时，友善和礼貌可以让彼此更愉快！', `name_zhtw` = '|cffffd100小提示:|r與其他玩家互動時厚道一點友誼才能細水長流!', `name_eses` = '|cffffd100Consejo:|r Recuerda ser amable al interactuar con otros jugadores y verás todas las puertas que se te abren.|n', `name_esmx` = '|cffffd100Consejo:|r Recuerda ser amable al interactuar con otros jugadores y verás todas las puertas que se te abren.|n', `name_ruru` = '|cffffd100Совет:|r При общении с другими игроками не забывайте, что доброта украшает мир!' WHERE `id` = 404;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 여행 중에 길을 따라가면 몬스터의 습격을 받을 위험이 거의 없습니다.', `name_frfr` = '|cffffd100Astuce :|r Vos chances de rencontrer des monstres errants sont réduites si vous restez sur les routes.', `name_dede` = '|cffffd100Tipp:|r Folgt dem Verlauf einer Straße, wenn Ihr unfreundliche Begegnungen mit Kreaturen vermeiden wollt.', `name_zhcn` = '|cffffd100小窍门：|r 当你沿着大路走的时候，碰到游荡怪物的可能性会小许多。', `name_zhtw` = '|cffffd100小提示:|r沿著路走你就不易與閒晃的怪物正面交鋒。', `name_eses` = '|cffffd100Consejo:|r Si no te sales de los caminos, tienes menos posibilidades de toparte con monstruos que deambulan.', `name_esmx` = '|cffffd100Consejo:|r Si no te sales de los caminos, tienes menos posibilidades de toparte con monstruos que deambulan.', `name_ruru` = '|cffffd100Совет:|r На дорогах вы гораздо меньше рискуете столкнуться с бродячими монстрами.' WHERE `id` = 405;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 던전 찾기를 이용하여 빠르게 던전을 탐험하거나 플레이어를 찾아 던전 파티를 결성해 보세요.', `name_frfr` = '|cffffd100Astuce :|r Utilisez l\'outil Donjons pour voyager rapidement vers un donjon ou pour trouver des membres supplémentaires pour votre groupe de donjon.', `name_dede` = '|cffffd100Tipp:|r Nutzt den Dungeonbrowser, um schnell zu Dungeons zu reisen oder um weitere Mitglieder für Eure Dungeongruppe zu finden.', `name_zhcn` = '|cffffd100小窍门：|r使用寻求组队界面可以加入一支队伍，或者找到其他玩家来加入你的队伍。', `name_zhtw` = '|cffffd100小提示:|r使用地城搜尋器快速前往地城或幫你的地城隊伍尋找更多成員。', `name_eses` = '|cffffd100Consejo:|r Usa la herramienta buscador de mazmorras para viajar deprisa a las mazmorras o para encontrar más jugadores para tu grupo de mazmorra.', `name_esmx` = '|cffffd100Consejo:|r Usa la herramienta buscador de mazmorras para viajar deprisa a las mazmorras o para encontrar más jugadores para tu grupo de mazmorra.', `name_ruru` = '|cffffd100Совет:|r Чтобы быстро перенестись в подземелье или найти игроков в группу, воспользуйтесь поиском подземелий.' WHERE `id` = 406;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 친구를 아제로스로 초대하셨나요? 그렇다면 꼭 친구와 함께 모험을 즐겨보세요.', `name_frfr` = '|cffffd100Astuce :|r Amenez vos amis en Azeroth, mais n’oubliez pas pour autant de les voir en dehors d’Azeroth.', `name_dede` = '|cffffd100Tipp:|r Bringt Eure Freunde nach Azeroth, aber geht auch mal mit ihnen nach draußen.', `name_zhcn` = '|cffffd100小窍门：|r 把你的朋友带到艾泽拉斯来，同时也别忘了和他们一起到户外去玩！', `name_zhtw` = '|cffffd100小提示:|r帶你的朋友到艾澤拉斯，不過也別忘了和他們到艾澤拉斯外面看看。', `name_eses` = '|cffffd100Consejo:|r Trae a tus amigos a Azeroth, pero no olvides quedar con ellos también fuera.|n', `name_esmx` = '|cffffd100Consejo:|r Trae a tus amigos a Azeroth, pero no olvides quedar con ellos también fuera.|n', `name_ruru` = '|cffffd100Совет:|r Приводите своих друзей в Азерот, но не забывайте встречаться с ними и за его пределами.' WHERE `id` = 407;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 미니맵 주위에 편지 봉투 아이콘이 표시되면 새로운 우편이 도착했다는 뜻입니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous videz régulièrement votre boîte à lettre, l’icône de courrier vous avertira en cas de nouveaux messages !', `name_dede` = '|cffffd100Tipp:|r Leert Euren Briefkasten regelmäßig, dann verrät Euch das Briefsymbol an Eurer Minikarte, dass Euch Post erwartet!', `name_zhcn` = '|cffffd100小窍门：|r 如果你保持邮箱空空如也，那么当你看到新邮件图标的时候，你就知道有人给你写信了！', `name_zhtw` = '|cffffd100小提示:|r如果你讓郵箱保持在空的狀態，郵件圖示將讓你知道何時有新郵件進來!', `name_eses` = '|cffffd100Consejo:|r ¡Si mantienes tu buzón de correo vacío, un icono de correo te alertará cuando recibas correo nuevo!|n', `name_esmx` = '|cffffd100Consejo:|r ¡Si mantienes tu buzón de correo vacío, un icono de correo te alertará cuando recibas correo nuevo!|n', `name_ruru` = '|cffffd100Совет:|r Если ваш почтовый ящик пуст, то при получении нового письма вы увидите значок в виде конверта.' WHERE `id` = 409;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 절대 다른 플레이어에게 계정 정보를 알려주지 마십시오.', `name_frfr` = '|cffffd100Astuce :|r Ne donnez jamais les informations relatives à votre compte à un autre joueur.', `name_dede` = '|cffffd100Tipp:|r Gebt niemals Eure Accountinformationen an andere Spieler weiter.', `name_zhcn` = '|cffffd100小窍门：|r 永远不要和其他人共享你的账号。', `name_zhtw` = '|cffffd100小提示:|r永遠不要透露你的帳號資料給其他玩家。', `name_eses` = '|cffffd100Consejo:|r Nunca des a otro jugador la información de tu cuenta.', `name_esmx` = '|cffffd100Consejo:|r Nunca des a otro jugador la información de tu cuenta.', `name_ruru` = '|cffffd100Совет:|r Никогда не передавайте другим игрокам информацию о вашей учетной записи.' WHERE `id` = 410;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 계정 정보를 타인과 공유하면 보안상 치명적인 문제가 발생할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Partager un compte avec quelqu\'un d\'autre peut compromettre sa sécurité.', `name_dede` = '|cffffd100Tipp:|r Teilt man sich einen Account mit anderen, besteht immer ein Sicherheitsrisiko.', `name_zhcn` = '|cffffd100小窍门：|r 与他人共享账号有可能使你失去它。', `name_zhtw` = '|cffffd100小提示:|r與他人共同使用一個帳號會危害其安全性。', `name_eses` = '|cffffd100Consejo:|r Si compartes la cuenta con otra persona, estás poniéndola en peligro.|n', `name_esmx` = '|cffffd100Consejo:|r Si compartes la cuenta con otra persona, estás poniéndola en peligro.|n', `name_ruru` = '|cffffd100Совет:|r Не рекомендуется использовать одну учетную запись на двоих, это небезопасно.' WHERE `id` = 411;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 메뉴에서 오늘의 팁을 켜거나 끌 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez désactiver ces astuces dans le menu Interface.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt die \'Tipps des Tages\' im Optionsmenü deaktivieren.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面设置选项中关闭这些小窍门的显示。', `name_zhtw` = '|cffffd100小提示:|r你可以在介面選單中關閉這些小提示。', `name_eses` = '|cffffd100Consejo:|r Los consejos se pueden desactivar en el menú de la interfaz.', `name_esmx` = '|cffffd100Consejo:|r Los consejos se pueden desactivar en el menú de la interfaz.', `name_ruru` = '|cffffd100Совет:|r Отображение этих советов можно отключить в меню настройки интерфейса.' WHERE `id` = 412;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 같은 파티에 속하지 않은 플레이어가 몬스터에게 피해를 먼저 주었을 경우 몬스터의 생명력바가 회색으로 표시되며, 이때는 해당 몬스터를 죽여도 경험치나 전리품을 획득할 수 없습니다.', `name_frfr` = '|cffffd100Astuce :|r Lorsqu’un monstre est blessé par un personnage qui n’appartient pas à votre groupe, sa barre de vie devient grise. Il ne vous rapportera ni butin ni expérience même si vous le tuez.', `name_dede` = '|cffffd100Tipp:|r Fügt ein Spieler, der nicht zu Eurer Gruppe gehört, einem Monster eher Schaden zu als Ihr, wird dessen Gesundheitsanzeige in grau angezeigt und Ihr erhaltet weder Beute, noch Erfahrung für dessen Tötung.', `name_zhcn` = '|cffffd100小窍门：|r 当一个不在你的队伍中的玩家首先对某个怪物造成伤害之后，该怪物的生命条会显示为灰色，表示你无法在杀死它之后获得经验值或物品。', `name_zhtw` = '|cffffd100小提示:|r當一個跟你不同隊伍的玩家比你先對怪物造成傷害時，此怪物將會呈現灰色的目標欄並且不會給你任何的經驗值或者戰利品。', `name_eses` = '|cffffd100Consejo:|r Cuando un jugador que no está en tu grupo inflige daño a un monstruo antes que tú, el monstruo tendrá la barra de salud de color gris y si lo matas, no conseguirás ni botín ni experiencia.|n', `name_esmx` = '|cffffd100Consejo:|r Cuando un jugador que no está en tu grupo inflige daño a un monstruo antes que tú, el monstruo tendrá la barra de salud de color gris y si lo matas, no conseguirás ni botín ni experiencia.|n', `name_ruru` = '|cffffd100Совет:|r Если противника до вас ранил игрок, не входящий в вашу группу, то индикатор здоровья этого противника окрасится серым, а за его убийство вы не получите ни добычи, ни опыта.' WHERE `id` = 419;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 설정 중 전투 설정에 있는 "시전바 표시" 설정을 켜면 선택한 대상이 어떤 주문을 시전 중인지 알 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Activer l’option « Barre de sorts », dans les options d’interface de combat, vous permet de voir le sort que votre cible actuelle est en train de lancer.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Euch den von Eurem momentan anvisierten Ziel gewirkten Zauber anzeigen lassen, indem Ihr die Option \'Zauberbalken\' im Interfacemenü aktiviert.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过在基础界面设置选项中打开“施法条”来观察你的当前目标正在施放的法术。', `name_zhtw` = '|cffffd100小提示:|r你可以開啟基本介面選項的「顯示敵人施法條」選項來觀看你目前的目標正在施放的法術。', `name_eses` = '|cffffd100Consejo:|r Si activas la opción \'Barras de lanzamiento\' en la pestaña de opciones de la interfaz de combate, verás el hechizo que tu objetivo actual está lanzando.|n', `name_esmx` = '|cffffd100Consejo:|r Si activas la opción \'Barras de lanzamiento\' en la pestaña de opciones de la interfaz de combate, verás el hechizo que tu objetivo actual está lanzando.|n', `name_ruru` = '|cffffd100Совет:|r В меню настройки интерфейса боя можно включить отображение заклинаний, применяемых противником.' WHERE `id` = 420;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 지도를 펼쳐 보려면 미니맵 우측 상단의 지도 버튼이나 키보드의 \'M\' 키를 누릅니다. 지도를 보면 퀘스트 완료 지점을 찾아가는 데 도움이 됩니다.', `name_frfr` = '|cffffd100Astuce :|r Pour voir la carte, appuyez sur la touche « M » ou cliquez sur le bouton qui se trouve en haut à droite de la minicarte. La carte vous aide à localiser les endroits où vous pourrez achever une quête.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt die Karte entweder durch einen Klick auf das Kartensymbol oben rechts an der Minikarte oder durch das Drücken der Taste \'M\' aufrufen. Die Karte kann Euch dabei behilflich sein, ein Questziel zu finden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过点击微缩地图左上角的地图按钮或点击快捷键M来打开地图。通过地图可以找到完成任务所需到达的位置。', `name_zhtw` = '|cffffd100小提示:|r你可以點擊小地圖右上角的地圖按鈕或者按「M」鍵以打開地圖介面。地圖可以幫你找到完成目前任務所需要前往的地點。', `name_eses` = '|cffffd100Consejo:|r Puedes acceder al mapa haciendo clic en el botón del mapa de la parte superior derecha del minimapa o pulsando la tecla M. El mapa puede ayudarte a ver adónde tienes que ir para completar una misión.|n', `name_esmx` = '|cffffd100Consejo:|r Puedes acceder al mapa haciendo clic en el botón del mapa de la parte superior derecha del minimapa o pulsando la tecla M. El mapa puede ayudarte a ver adónde tienes que ir para completar una misión.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы развернуть карту, щелкните по соответствующему значку в верхнем правом углу мини-карты или нажмите клавишу M (ь). Карта поможет вам определить, куда необходимо отправиться для выполнения задания.' WHERE `id` = 422;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대부분의 고레벨 던전은 영웅 난이도를 설정할 수 있습니다. 영웅 난이도는 상위 레벨 플레이어들의 수준에 맞춰져 있으며 더 좋은 전리품을 획득할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r De nombreux donjons de haut niveau ont un mode Héroïque. Lorsqu’ils sont joués en mode Héroïque, ils sont adaptés à des personnages de niveau plus élevé, et disposent de butins améliorés.', `name_dede` = '|cffffd100Tipp:|r Viele hochstufige Dungeons können auf dem Schwierigkeitsgrad \'Heroisch\' gespielt werden. Dungeons des Schwierigkeitsgrads \'Heroisch\' sind auf hochstufige Charaktere abgestimmt und bieten hochwertigere Beute.', `name_zhcn` = '|cffffd100小窍门：|r 许多高等级的地下城都有英雄模式的选项。英雄模式地下城适合高等级的玩家，掉落的装备也更好。', `name_zhtw` = '|cffffd100小提示:|r許多高等級的地城擁有英雄模式。英雄模式的地城中適合等級更高的玩家，也有更好的戰利品。', `name_eses` = '|cffffd100Consejo:|r Muchas mazmorras de alto nivel se pueden configurar en modo Heroico. Las mazmorras de este modo están pensadas para jugadores de mayor nivel y en ellas se obtiene un botín mejorado.|n', `name_esmx` = '|cffffd100Consejo:|r Muchas mazmorras de alto nivel se pueden configurar en modo Heroico. Las mazmorras de este modo están pensadas para jugadores de mayor nivel y en ellas se obtiene un botín mejorado.|n', `name_ruru` = '|cffffd100Совет:|r Во многих высокоуровневых подземельях предусмотрен героический уровень сложности. Подземелья на героическом уровне сложности предназначены для персонажей более высоких уровней, и в них дают гораздо более ценную добычу.' WHERE `id` = 423;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 명예 점수를 사용하여 용사의 전당(얼라이언스)이나 전설의 전당(호드)에서 강력한 보상 아이템을 구입할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Achetez de puissantes récompenses avec vos points d’honneur au Hall des champions (Alliance) ou au Hall des légendes (Horde).', `name_dede` = '|cffffd100Tipp:|r Tauscht Eure Ehrenpunkte gegen mächtige Belohnungen in der Halle der Champions (Allianz) und in der Halle der Legenden (Horde) ein.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在勇士大厅（联盟）或传说大厅（部落）花费你的荣誉点数来购买强大的奖励物品。', `name_zhtw` = '|cffffd100小提示:|r你可以在勇士大廳(聯盟)或者傳說大廳(部落)使用你的榮譽點數購買戰場裝備。', `name_eses` = '|cffffd100Consejo:|r Gasta tus puntos de honor para obtener poderosas recompensas en la Sala de los Campeones (Alianza) o en la Sala de las Leyendas (Horda).|n', `name_esmx` = '|cffffd100Consejo:|r Gasta tus puntos de honor para obtener poderosas recompensas en la Sala de los Campeones (Alianza) o en la Sala de las Leyendas (Horda).|n', `name_ruru` = '|cffffd100Совет:|r За очки чести можно получить ценные награды в Зале Защитников (Альянс) или Зале Легенд (Орда).' WHERE `id` = 424;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 그날 얻은 명예 점수는 즉시 사용이 가능합니다. 플레이어간 전투창에서 명예 점수를 얼마나 사용할 수 있는지 살펴보실 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les points d’honneur gagnés un jour sont disponibles immédiatement. Pour voir de combien de points vous disposez, consultez l’interface JcJ.', `name_dede` = '|cffffd100Tipp:|r Die Ehrenpunkte, die man sich tagtäglich verdienen kann, können sofort ausgegeben werden. Seht im PvP-Interface nach, wie viele Punkte Euch zur Verfügung stehen.', `name_zhcn` = '|cffffd100小窍门：|r 你每天获得的荣誉点数都可以立即使用。在PvP界面中可以看到你所拥有的荣誉点数。', `name_zhtw` = '|cffffd100小提示:|r每日獲得的榮譽點數變成可立即使用。PVP介面可以顯示你目前擁有多少榮譽點數可以使用。', `name_eses` = '|cffffd100Consejo:|r Los puntos de honor que ganas cada día estarán disponibles de manera inmediata. Comprueba cuántos puntos puedes gastar en la interfaz JcJ.|n', `name_esmx` = '|cffffd100Consejo:|r Los puntos de honor que ganas cada día estarán disponibles de manera inmediata. Comprueba cuántos puntos puedes gastar en la interfaz JcJ.|n', `name_ruru` = '|cffffd100Совет:|r Заработанные очки чести вы можете потратить незамедлительно. Чтобы узнать, сколько у вас очков, воспользуйтесь вкладкой PvP.' WHERE `id` = 425;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 던전 앞에 있는 만남의 돌을 사용하여 멀리 떨어진 파티원을 소환할 수 있습니다. 파티원을 소환하려면 만남의 돌 위치에 2명의 플레이어가 있어야 합니다.', `name_frfr` = '|cffffd100Astuce :|r Les pierres de rencontre servent à invoquer les membres du groupe qui ne sont pas sur place. Pour cela, il faut que deux personnages se trouvent près de la pierre.', `name_dede` = '|cffffd100Tipp:|r Die Versammlungssteine von Dungeons können dazu verwendet werden, abwesende Gruppenmitglieder herbeizubeschwören. Für eine Beschwörung sind zwei Spieler am Versammlungsstein erforderlich.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用地下城外的集合石来召唤远处的队友。两个玩家在集合石旁即可开始召唤。', `name_zhtw` = '|cffffd100小提示:|r地城集合石可以用來召喚不在場的隊友。需要兩名隊員同時進行召喚。', `name_eses` = '|cffffd100Consejo:|r Se pueden usar las rocas de encuentro de las mazmorras para invocar a miembros de tu grupo ausentes. Hacen falta dos jugadores junto a la roca para la invocación.|n', `name_esmx` = '|cffffd100Consejo:|r Se pueden usar las rocas de encuentro de las mazmorras para invocar a miembros de tu grupo ausentes. Hacen falta dos jugadores junto a la roca para la invocación.|n', `name_ruru` = '|cffffd100Совет:|r Отсутствующих членов группы можно призвать в подземелье при помощи камня призыва. Для этого возле камня должны находиться как минимум два игрока.' WHERE `id` = 426;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 계정 관리의 자녀 보호 설정을 이용하여 플레이 시간을 관리할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r La partie Contrôle parental du site de Gestion de compte vous propose des outils pour vous aider à gérer votre temps de jeu.', `name_dede` = '|cffffd100Tipp:|r Einstellungshilfen für die Verwaltung Eurer Spielzeit findet Ihr im Bereich Elterliche Freigabe der Accountverwaltungsseite.', `name_zhcn` = '|cffffd100小窍门：|r 绑定并经常更换矩阵卡可以让你的帐号更安全。', `name_zhtw` = '|cffffd100小提示:|r帳號管理畫面的主要選項區提供了工具選項來幫助你管理遊戲時間。', `name_eses` = '|cffffd100Consejo:|r En la sección de control parental del sitio de Administración de cuentas hay herramientas para administrar el tiempo de juego.|n', `name_esmx` = '|cffffd100Consejo:|r En la sección de control parental del sitio de Administración de cuentas hay herramientas para administrar el tiempo de juego.|n', `name_ruru` = '|cffffd100Совет:|r На странице управления учетной записью есть раздел родительского контроля. В этом разделе вы сможете поставить ограничения на игровое время.' WHERE `id` = 427;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 은행에 보관 중인 퀘스트 아이템으로는 퀘스트를 완료할 수 없습니다.', `name_frfr` = '|cffffd100Astuce :|r Les objets de quête qui se trouvent en banque ne peuvent être utilisés pour terminer une quête.', `name_dede` = '|cffffd100Tipp:|r Eine Quest kann nicht abgeschlossen werden, wenn der benötigte Questgegenstand in der Bank eingelagert ist.', `name_zhcn` = '|cffffd100小窍门：|r 如果你把任务物品放在银行中，就无法完成必须通过上缴该物品才能完成的任务。', `name_zhtw` = '|cffffd100小提示:|r銀行裡的任務物品無法用來完成任務。', `name_eses` = '|cffffd100Consejo:|r Los objetos de misión que están en el banco no pueden ser utilizados para completar misiones.|n', `name_esmx` = '|cffffd100Consejo:|r Los objetos de misión que están en el banco no pueden ser utilizados para completar misiones.|n', `name_ruru` = '|cffffd100Совет:|r Вы не сможете завершить задание, если необходимый для него предмет находится в банке.' WHERE `id` = 428;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 퀘스트 목록에 (실패)라고 표시된 퀘스트는 퀘스트 NPC에게 다시 퀘스트를 받을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Une quête pour laquelle est indiqué un (Échec) dans le journal de quêtes peut être reprise auprès du personnage qui la proposait.', `name_dede` = '|cffffd100Tipp:|r Eine Quest, die im Questlog als (Fehlgeschlagen) markiert ist, kann beim Questgeber erneut angenommen werden.', `name_zhcn` = '|cffffd100小窍门：|r 被标记为（失败）的任务可以放弃并重新在任务给予人那里接到。', `name_zhtw` = '|cffffd100小提示:|r你可以先放棄任務記錄中標示(失敗)的任務再向任務給予者重新取得該任務。', `name_eses` = '|cffffd100Consejo:|r Podrás recuperar del asignador de misiones una misión que esté marcada como (Fallada) en el registro de misiones.|n', `name_esmx` = '|cffffd100Consejo:|r Podrás recuperar del asignador de misiones una misión que esté marcada como (Fallada) en el registro de misiones.|n', `name_ruru` = '|cffffd100Совет:|r Задания с пометкой «Неудача» можно заново получить у того же персонажа.' WHERE `id` = 429;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 퀘스트 이름 왼편의 숫자는 같은 퀘스트를 수행하는 파티원의 수를 나타냅니다.', `name_frfr` = '|cffffd100Astuce :|r Le nombre qui apparaît à côté du nom d\'une quête dans le journal indique le nombre de personnes de votre groupe qui l\'ont aussi à accomplir.', `name_dede` = '|cffffd100Tipp:|r Die Zahl neben dem Questtitel in Eurem Questlog zeigt an, wie viele weitere Mitglieder Eurer Gruppe diese Quest ebenfalls angenommen haben.', `name_zhcn` = '|cffffd100小窍门：|r 任务名旁边的数字代表你的小队中有多少人也在做这个任务。', `name_zhtw` = '|cffffd100小提示:|r任務記錄中出現在任務旁的數字說明有多少隊友也接下該任務。', `name_eses` = '|cffffd100Consejo:|r El número junto al nombre de una misión en tu registro muestra cuantos miembros de tu grupo están realizando esa misión.|n', `name_esmx` = '|cffffd100Consejo:|r El número junto al nombre de una misión en tu registro muestra cuantos miembros de tu grupo están realizando esa misión.|n', `name_ruru` = '|cffffd100Совет:|r Цифра рядом с названием задания в вашем журнале обозначает количество игроков из вашей группы, выполняющих это же задание.' WHERE `id` = 430;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 공격대에 참여한 상태로는 (공격대) 퀘스트 임무만 수행할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Lorsque vous faites partie d\'un groupe de raid, vous ne pouvez faire progresser que les quêtes marquées pour (Raid).', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr Mitglied eines Schlachtzugs seid, könnt Ihr nur Quests absolvieren, die mit (Schlachtzug) markiert sind.', `name_zhcn` = '|cffffd100小窍门：|r 当你在团队中时，就无法完成除了标记为（团队）的任务之外的其它任务。', `name_zhtw` = '|cffffd100小提示:|r當處於團隊中時，你無法進行(團隊)任務以外的任務。', `name_eses` = '|cffffd100Consejo:|r Cuando estás en una banda, solo puedes realizar misiones de banda.|n', `name_esmx` = '|cffffd100Consejo:|r Cuando estás en una banda, solo puedes realizar misiones de banda.|n', `name_ruru` = '|cffffd100Совет:|r Находясь в рейде, вы не можете выполнять никаких заданий, кроме тех, что помечены как рейдовые.' WHERE `id` = 431;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 경매장에서 한번 입찰하면 취소할 수 없습니다. 입찰 여부는 신중히 결정하세요.', `name_frfr` = '|cffffd100Astuce :|r Il n\'est pas possible d\'annuler vos enchères à l\'hôtel des ventes, placez-les avec prudence.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Eure Gebote im Auktionshaus nicht rückgängig machen. Bietet daher mit Bedacht.', `name_zhcn` = '|cffffd100小窍门：|r 你不能取消自己对拍卖物品的出价，所以竞拍时要谨慎。', `name_zhtw` = '|cffffd100小提示:|r你不能取消在拍賣場的競標，所以請小心出價。', `name_eses` = '|cffffd100Consejo:|r No puedes cancelar tus pujas en la casa de subastas, así que puja con cuidado.|n', `name_esmx` = '|cffffd100Consejo:|r No puedes cancelar tus pujas en la casa de subastas, así que puja con cuidado.|n', `name_ruru` = '|cffffd100Совет:|r Вы не можете отменить свои ставки на аукционе, поэтому будьте внимательны, когда их делаете.' WHERE `id` = 432;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대화 채널에 입장하려면 /입장 [채널이름]을, 퇴장하려면 /퇴장 [채널이름]을 입력하세요.', `name_frfr` = '|cffffd100Astuce :|r Pour entrer sur un canal de discussion, tapez /rejoindre [nom du canal]. Pour le quitter, tapez /partir [nom du canal].', `name_dede` = '|cffffd100Tipp:|r Gebt /beitreten [Channelname] ein, um einem Chatchannel beizutreten, und /verlassen [Channelname], um ihn wieder zu verlassen.', `name_zhcn` = '|cffffd100小窍门：|r 要加入某个聊天频道，可以使用/join [频道名]命令；退出聊天频道则使用/leave [频道名]命令。', `name_zhtw` = '|cffffd100小提示:|r要進入一個對話頻道，請輸入/join [頻道名稱]，而輸入/leave [頻道名稱]則可以離開該頻道。', `name_eses` = '|cffffd100Consejo:|r Para entrar en un canal de chat escribe /unirse [nombre del canal] y /dejar [nombre del canal] para salir.|n', `name_esmx` = '|cffffd100Consejo:|r Para entrar en un canal de chat escribe /unirse [nombre del canal] y /dejar [nombre del canal] para salir.|n', `name_ruru` = '|cffffd100Совет:|r Чтобы присоединиться к каналу чата, введите /войти [название канала]. Чтобы покинуть канал, введите /уйти [название канала].' WHERE `id` = 433;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 우편물은 최대 30일까지만 보관되며 그 이후엔 사라집니다.', `name_frfr` = '|cffffd100Astuce :|r Le courrier est conservé 30 jours au maximum avant de disparaître.', `name_dede` = '|cffffd100Tipp:|r Post bleibt für maximal 30 Tage im Postfach erhalten, danach verschwindet sie.', `name_zhcn` = '|cffffd100小窍门：|r 邮件可以在信箱中保留最多30天。', `name_zhtw` = '|cffffd100小提示:|r郵件在消失之前最久可保存30天。', `name_eses` = '|cffffd100Consejo:|r El correo se guardará un máximo de 30 días antes de desaparecer.|n', `name_esmx` = '|cffffd100Consejo:|r El correo se guardará un máximo de 30 días antes de desaparecer.|n', `name_ruru` = '|cffffd100Совет:|r Почта хранится тридцать дней, а затем удаляется.' WHERE `id` = 434;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 획득한 열쇠는 가방 왼편에 있는 열쇠고리에 보관됩니다.', `name_frfr` = '|cffffd100Astuce :|r Lorsque vous recevez une clé, elle est placée dans le trousseau de clés qui se trouve à gauche de vos autres sacs.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr einen Schlüssel bekommt, wird dieser in Eurem Schlüsselbund links neben Euren Taschen abgelegt.', `name_zhcn` = '|cffffd100小窍门：|r 当你得到新的钥匙之后，可以在背包左边的钥匙链中找到它们。', `name_zhtw` = '|cffffd100小提示:|r一旦你獲得一把鑰匙，你就能在背包左邊的特殊鑰匙圈包包裡找到它們。', `name_eses` = '|cffffd100Consejo:|r Las llaves se encuentran en una bolsa llavero especial que está a la izquierda de tus bolsas.|n', `name_esmx` = '|cffffd100Consejo:|r Las llaves se encuentran en una bolsa llavero especial que está a la izquierda de tus bolsas.|n', `name_ruru` = '|cffffd100Совет:|r Если вы найдете ключ, он наденется на колечко, расположенное слева от сумок.' WHERE `id` = 435;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 대도시 경비병에게 말을 걸면 길안내를 받을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les gardes d\'une ville peuvent souvent vous indiquer où trouver certains endroits importants de la ville.', `name_dede` = '|cffffd100Tipp:|r Die Stadtwachen können Euch oft den Weg zu anderen Orten von Interesse in der Stadt weisen.', `name_zhcn` = '|cffffd100小窍门：|r 城市中的卫兵通常会告诉你城里的各个重要地点的位置。', `name_zhtw` = '|cffffd100小提示:|r城市的守衛通常會提供你前往城市中其他地點的指示。', `name_eses` = '|cffffd100Consejo:|r Los guardias de las ciudades a menudo te dirán cómo llegar a otras zonas importantes de la ciudad.|n', `name_esmx` = '|cffffd100Consejo:|r Los guardias de las ciudades a menudo te dirán cómo llegar a otras zonas importantes de la ciudad.|n', `name_ruru` = '|cffffd100Совет:|r Стражи всегда подскажут вам, как пройти в то или иное место в городе.' WHERE `id` = 437;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 최근에 상인에게 판 물건은 재매입 탭을 클릭하여 다시 구입할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez racheter les objets vendus récemment à un marchand grâce à l\'onglet de rachat.', `name_dede` = '|cffffd100Tipp:|r Gegenstände, die erst kürzlich an einen Händler verkauft wurden, können über die Schaltfläche \'Rückkauf\' zurückerworben werden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过“购回”标签购买自己刚刚卖给商人的物品。', `name_zhtw` = '|cffffd100小提示:|r你可以用買回鍵重新購買最近賣給商人的物品。', `name_eses` = '|cffffd100Consejo:|r Puedes volver a comprar objetos que has vendido hace poco usando la pestaña recuperar.|n', `name_esmx` = '|cffffd100Consejo:|r Puedes volver a comprar objetos que has vendido hace poco usando la pestaña recuperar.|n', `name_ruru` = '|cffffd100Совет:|r Вы можете заново приобрести у торговца недавно проданные предметы, перейдя на вкладку выкупа.' WHERE `id` = 438;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 파티장은 자신의 초상화를 오른쪽 클릭하여 인스턴스를 초기화하거나 던전 난이도를 변경할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Le chef d\'un groupe peut réinitialiser ses instances ou en modifier la difficulté grâce au menu disponible par clic droit sur son portrait.', `name_dede` = '|cffffd100Tipp:|r Ein Gruppenanführer kann eine Instanz zurücksetzen oder den Schwierigkeitsgrad des Dungeons ändern, indem er auf sein Portrait rechtsklickt und die entsprechende Option auswählt.', `name_zhcn` = '|cffffd100小窍门：|r 小队的队长可以通过右键点击自己的头像来重置副本或更改地下城难度。', `name_zhtw` = '|cffffd100小提示:|r隊伍的隊長可以用右鍵點擊自己的頭像，從清單中選擇重置副本或調整地城難度。', `name_eses` = '|cffffd100Consejo:|r El líder de un grupo puede reiniciar las estancias o cambiar la dificultad de una mazmorra haciendo clic derecho sobre su retrato.', `name_esmx` = '|cffffd100Consejo:|r El líder de un grupo puede reiniciar las estancias o cambiar la dificultad de una mazmorra haciendo clic derecho sobre su retrato.', `name_ruru` = '|cffffd100Совет:|r Лидер группы может обновить подземелье или изменить его уровень сложности. Для этого ему нужно щелкнуть правой кнопкой мыши по своему портрету и выбрать соответствующий пункт в появившемся меню.' WHERE `id` = 439;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 귀환석을 잃어버렸을 때는 아무 여관주인에게나 말을 걸면 새로 받을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r N\'importe quel aubergiste pourra toujours vous fournir une nouvelle pierre de foyer.', `name_dede` = '|cffffd100Tipp:|r Jeder Gastwirt kann Euch jederzeit wieder einen neuen Ruhestein geben.', `name_zhcn` = '|cffffd100小窍门：|r 你随时可以从任意旅店老板那里获得新的炉石。', `name_zhtw` = '|cffffd100小提示:|r你可以隨時向任何一位旅店老闆索取新的爐石。', `name_eses` = '|cffffd100Consejo:|r Cualquier tabernero te puede dar una piedra de hogar nueva.|n', `name_esmx` = '|cffffd100Consejo:|r Cualquier tabernero te puede dar una piedra de hogar nueva.|n', `name_ruru` = '|cffffd100Совет:|r Новый камень возвращения можно получить у любого хозяина таверны.' WHERE `id` = 440;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r Shift + M 키를 누르거나 세계 지도 선택 메뉴의 설정으로 위치한 지역의 작은 지역 지도를 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez afficher une petite carte de votre zone soit en appuyant sur Maj-M, soit en activant l\'option à partir de la carte du monde.', `name_dede` = '|cffffd100Tipp:|r Indem Ihr Shift-M drückt oder die Option auf der Weltkarte auswählt, könnt Ihr eine kleine Karte des Gebiets, in dem Ihr Euch momentan befindet, öffnen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过Shift-M打开当前区域的小地图，或者在世界地图中设置这一选项。', `name_zhtw` = '|cffffd100小提示:|r你可以按下Shift+M鍵，或是由世界地圖的選項中打開目前所在區域的小地圖。', `name_eses` = '|cffffd100Consejo:|r Puedes abrir un pequeño mapa de la zona actual bien con Mayús-M o como una opción del menú del mundo.', `name_esmx` = '|cffffd100Consejo:|r Puedes abrir un pequeño mapa de la zona actual bien con Mayús-M o como una opción del menú del mundo.', `name_ruru` = '|cffffd100Совет:|r Чтобы отобразить маленькую карту игровой зоны, в которой вы находитесь, нажмите Shift + M или выберите соответствующий пункт в меню карты мира.' WHERE `id` = 441;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 뒤에서 가해지는 공격은 피하거나, 무기로 막거나, 방패로 막을 수 없습니다.', `name_frfr` = '|cffffd100Astuce :|r Les personnages-joueurs ne peuvent pas esquiver, parer ou bloquer les attaques qui arrivent de derrière eux.', `name_dede` = '|cffffd100Tipp:|r Spieler können Angriffe, die von hinten kommen, nicht parieren, blocken oder ihnen ausweichen.', `name_zhcn` = '|cffffd100小窍门：|r 玩家无法躲闪、招架或格挡来自背后的攻击。', `name_zhtw` = '|cffffd100小提示:|r玩家無法閃躲、招架或格擋來自於背後的攻擊。', `name_eses` = '|cffffd100Consejo:|r Los jugadores no pueden esquivar, parar o bloquear ataques por la espalda.', `name_esmx` = '|cffffd100Consejo:|r Los jugadores no pueden esquivar, parar o bloquear ataques por la espalda.', `name_ruru` = '|cffffd100Совет:|r Игроки не могут парировать и блокировать атаки, проводимые со спины, а также уклоняться от них.' WHERE `id` = 442;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 보석 장착 창에서 이미 보석이 장착된 보석 홈에 새로운 보석을 장착시키면 새 보석을 사용할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez remplacer une gemme déjà sertie dans un objet en posant une nouvelle gemme par-dessus dans l\'interface de sertissage.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt einen Edelstein, der bereits in Eurem Gegenstand gesockelt ist, ersetzen, indem Ihr im Sockelungsinterface einen neuen Edelstein über dem vorherigen platziert.', `name_zhcn` = '|cffffd100小窍门：|r 你可以向已经镶嵌了宝石的插孔中镶入新的宝石。', `name_zhtw` = '|cffffd100小提示:|r你可以在插槽介面中插入新的寶石來取代原先已插入裝備插槽中的寶石。', `name_eses` = '|cffffd100Consejo:|r Puedes reemplazar una gema que ya está en una ranura de un objeto dejando caer otra encima en la interfaz de ranuras.', `name_esmx` = '|cffffd100Consejo:|r Puedes reemplazar una gema que ya está en una ranura de un objeto dejando caer otra encima en la interfaz de ranuras.', `name_ruru` = '|cffffd100Совет:|r Вы можете заменить драгоценный камень, вставленный в ваш предмет, на другой, поместив новый самоцвет поверх него в окне инкрустирования.' WHERE `id` = 444;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전투 메시지를 마우스 오른쪽 클릭하면 여러 선택 목록이 나타납니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous cliquez droit sur un nom dans le journal de combat, une liste d\'options s\'affiche.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr im Kampflog mit der rechten Maustaste auf einen Namen klickt, wird Euch eine Liste mit verschiedenen Optionen angezeigt.', `name_zhcn` = '|cffffd100小窍门：|r 在战斗记录中右键点击一个名字，就可以看到更多相关选项。', `name_zhtw` = '|cffffd100小提示:|r使用右鍵點擊戰鬥記錄中的名稱會顯示一張選項列表。', `name_eses` = '|cffffd100Consejo:|r Si haces clic derecho en un nombre en el registro de combate, aparecerá una lista de opciones.', `name_esmx` = '|cffffd100Consejo:|r Si haces clic derecho en un nombre en el registro de combate, aparecerá una lista de opciones.', `name_ruru` = '|cffffd100Совет:|r Если вы щелкнете правой кнопкой мыши по имени в журнале боя, появится список параметров.' WHERE `id` = 445;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전투 비약과 강화 비약의 효과는 동시에 1개씩만 가질 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous ne pouvez avoir qu\'un Elixir de bataille et un Elixir du Gardien actifs en même temps.', `name_dede` = '|cffffd100Tipp:|r Es kann immer nur der Effekt von jeweils einem Kampfelixier und Wächterelixier auf Euch aktiv sein.', `name_zhcn` = '|cffffd100小窍门：|r 你在同一时间内只能带有一种作战药剂效果和一种守护药剂效果。', `name_zhtw` = '|cffffd100小提示:|r同一時間內你只能擁有一種作戰藥劑和一種守護藥劑的效果。', `name_eses` = '|cffffd100Consejo:|r Solo puedes tener un elixir de batalla y uno de guardián a la vez.', `name_esmx` = '|cffffd100Consejo:|r Solo puedes tener un elixir de batalla y uno de guardián a la vez.', `name_ruru` = '|cffffd100Совет:|r Вы можете находиться под влиянием только одного боевого эликсира и одного защитного эликсира одновременно.' WHERE `id` = 446;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 아이템에 마우스를 가져간 후 Shift 키를 누르면 자신이 착용 중인 해당 부위 아이템의 툴팁을 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Quand vous passez votre souris au-dessus d\'un objet, vous pouvez appuyer sur la touche Maj pour voir l\'objet de ce type que vous avez équipé.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr den Mauszeiger über einen Gegenstand haltet, werden bei gedrückter Umschalttaste zusätzlich zu den angezeigten Werten auch die Werte des entsprechenden, ausgerüsteten Gegenstandes angezeigt.', `name_zhcn` = '|cffffd100小窍门：|r 当你将鼠标放在一件物品上时，可以按下Shift键以显示装备在你身上的同类物品。', `name_zhtw` = '|cffffd100小提示:|r當你將游標移到一件物品上時，你可以按住shift鍵，這將會顯示你目前裝備的同類型物品。', `name_eses` = '|cffffd100Consejo:|r Si cuando pases el ratón por encima de un objeto mantienes pulsada la tecla Mayús, también verás el objeto de ese tipo que ya tienes equipado.', `name_esmx` = '|cffffd100Consejo:|r Si cuando pases el ratón por encima de un objeto mantienes pulsada la tecla Mayús, también verás el objeto de ese tipo que ya tienes equipado.', `name_ruru` = '|cffffd100Совет:|r Нажав Shift при наведении указателя мыши на предмет, можно увидеть характеристики аналогичного предмета, одетого на вашем персонаже.' WHERE `id` = 447;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 서버 당 최대 10개의 캐릭터를 생성할 수 있고 모든 서버에서 생성할 수 있는 최대 캐릭터 개수는 50개입니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez posséder jusqu\'à 10 personnages par royaume, dans la limite de 50 personnages tous royaumes confondus.', `name_dede` = '|cffffd100Tipp:|r Es können sich bis zu 10 Charaktere gleichzeitig auf einem Server befinden, das Maximum von erstellten Charakteren auf allen Servern liegt bei 50.', `name_zhcn` = '|cffffd100小窍门：|r 你在一个服务器内可以建立最多10个角色，在所有服务器上可以建立的角色总数是50个。', `name_zhtw` = '|cffffd100小提示:|r每個伺服器中你最多可以擁有10個角色，而所有伺服器的總和角色上限為50個。', `name_eses` = '|cffffd100Consejo:|r Puedes tener hasta 10 personajes por reino y un máximo de 50 personajes entre todos los reinos.', `name_esmx` = '|cffffd100Consejo:|r Puedes tener hasta 10 personajes por reino y un máximo de 50 personajes entre todos los reinos.', `name_ruru` = '|cffffd100Совет:|r В одном игровом мире можно создать до 10 персонажей. Максимальное количество персонажей во всех игровых мирах не должно превышать 50.' WHERE `id` = 448;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 최근 입력한 텍스트는 다시 사용할 수 있습니다. Enter 키를 누르신 후 Alt + 위 화살표 키를 누르면 전에 입력한 문구가 나타납니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez réutiliser un texte que vous avez récemment écrit. Appuyez sur Entrée, puis appuyez sur la touche <Alt> et la flèche vers le haut pour faire défiler vos précédents messages.', `name_dede` = '|cffffd100Tipp:|r Bereits geschriebener Text kann wieder aufgerufen werden. Nach dem Drücken der Entertaste kann man mit Hilfe von <Alt> + Pfeil-nach-oben-Taste durch die vorher gesendeten Nachrichten scrollen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以重复发送最近输入的信息。按下Enter键，然后使用<Alt>+上键就可以浏览你曾经发送的信息。', `name_zhtw` = '|cffffd100小提示:|r你可以重複使用先前輸入的訊息。首先按下Enter鍵，然後使用Alt + ↑鍵來挑選你之前輸入過的訊息。', `name_eses` = '|cffffd100Consejo:|r Puedes reutilizar un texto que hayas escrito recientemente. Pulsa Intro y usa <Alt> + Flecha arriba para moverte por los mensajes anteriores.', `name_esmx` = '|cffffd100Consejo:|r Puedes reutilizar un texto que hayas escrito recientemente. Pulsa Intro y usa <Alt> + Flecha arriba para moverte por los mensajes anteriores.', `name_ruru` = '|cffffd100Совет:|r Ранее набранный текст можно ввести повторно. Для этого нажмите Enter, а затем, нажимая одновременно Alt клавишу со стрелкой вверх, выберите нужное сообщение.' WHERE `id` = 449;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 캐릭터창의 소환수 탭에서 탈것과 애완동물을 소환할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vos montures et vos familiers pacifiques se trouvent sur l’onglet « Familiers » de votre feuille de personnage.', `name_dede` = '|cffffd100Tipp:|r Eure Reittiere und Gefährten können über den Tab "Begleiter" im Charakterfenster aufgerufen werden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过角色信息栏中的宠物标签查看并召唤自己所拥有的坐骑和非战斗宠物。', `name_zhtw` = '|cffffd100小提示:|r你的坐騎與非戰鬥夥伴能從角色頁面的寵物分頁中存取。', `name_eses` = '|cffffd100Consejo:|r Puedes acceder a tus monturas y compañeros mansos a través de la pestaña Mascotas de tu página de personaje.', `name_esmx` = '|cffffd100Consejo:|r Puedes acceder a tus monturas y compañeros mansos a través de la pestaña Mascotas de tu página de personaje.', `name_ruru` = '|cffffd100Совет:|r С помощью закладки «Питомцы» на странице персонажа можно увидеть ваших верховых животных и небоевых спутников.' WHERE `id` = 450;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 전장이나 영웅 던전에서 획득한 화폐는 화폐 창에서 확인할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les monnaies, comme celles que l’on récupère sur les champs de bataille ou dans les donjons héroïques, sont conservées dans le panneau Monnaies.', `name_dede` = '|cffffd100Tipp:|r Abzeichen, die man beispielsweise für Schlachtfelder oder heroische Dungeons erhält, werden unter dem Reiter \'Abz." im Charaktermenü gespeichert.', `name_zhcn` = '|cffffd100小窍门：|r 各种货币，比如你在战场或英雄副本中获得的代币类物品，都保存在货币页面中。', `name_zhtw` = '|cffffd100小提示:|r兌換通貨，例如從戰場上或英雄難度副本中收集的兌換物都儲存在兌換通貨頁面。', `name_eses` = '|cffffd100Consejo:|r Las monedas, como las obtenidas en los campos de batalla o las mazmorras heroicas, se almacenan en la página de monedas.', `name_esmx` = '|cffffd100Consejo:|r Las monedas, como las obtenidas en los campos de batalla o las mazmorras heroicas, se almacenan en la página de monedas.', `name_ruru` = '|cffffd100Совет:|r Платежные средства, полученные на полях боя или в подземельях героического уровня сложности, хранятся в закладке платежных средств.' WHERE `id` = 451;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 일부 탈것은 여러 사람을 태울 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Certains véhicules peuvent transporter plusieurs passagers.', `name_dede` = '|cffffd100Tipp:|r In einigen Fahrzeugen können mehrere Passagiere Platz finden.', `name_zhcn` = '|cffffd100小窍门：|r 某些载具可以有多人乘坐。', `name_zhtw` = '|cffffd100小提示:|r某些載具可以搭載多名乘客。', `name_eses` = '|cffffd100Consejo:|r Algunos vehículos pueden llevar a varios pasajeros.', `name_esmx` = '|cffffd100Consejo:|r Algunos vehículos pueden llevar a varios pasajeros.', `name_ruru` = '|cffffd100Совет:|r Некоторые транспортные средства могут перевозить нескольких пассажиров одновременно.' WHERE `id` = 452;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 필요한 숙련 기술을 익혔다면 아웃랜드와 노스렌드에서 나는 탈것을 탈 수 있습니다. 단, 노스렌드에서는 극지 비행 훈련을 완료해야 합니다.', `name_frfr` = '|cffffd100Astuce :|r Les montures volantes peuvent être utilisées en Outreterre lorsque vous avez le niveau approprié en Monte, et en Norfendre lorsque vous avez appris à voler par temps froid.', `name_dede` = '|cffffd100Tipp:|r In der Scherbenwelt können fliegende Reittiere nach dem Erlernen der dafür benötigten Fertigkeit genutzt werden, in Nordend erst nachdem der Kaltwetterflug erlernt wurde.', `name_zhcn` = '|cffffd100小窍门：|r 当你学习了最高级别的骑术之后，就可以在外域使用飞行坐骑；当你完成了寒冷天气飞行训练之后，就可以在诺森德使用飞行坐骑。', `name_zhtw` = '|cffffd100小提示:|r只要你達到適當的騎術技能等級，就能在外域使用飛行坐騎。而在北裂境則需要先接受寒冷氣候飛行的訓練。', `name_eses` = '|cffffd100Consejo:|r Podrás usar las monturas voladoras en Terrallende cuando consigas el nivel de equitación apropiado y en Rasganorte cuando aprendas Vuelo en clima frío.', `name_esmx` = '|cffffd100Consejo:|r Podrás usar las monturas voladoras en Terrallende cuando consigas el nivel de equitación apropiado y en Rasganorte cuando aprendas Vuelo en clima frío.', `name_ruru` = '|cffffd100Совет:|r Воздушные средства передвижения становятся доступны игрокам в Запределье после достижения определенного уровня навыка верховой езды, а в Нордсколе после овладения навыком «Полеты в непогоду».' WHERE `id` = 453;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 일부 업적을 성취하면 보상으로 전투에 영향을 안 미치는 고유 아이템을 얻을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Accomplir certains hauts faits donne accès à des récompenses, des objets uniques non liés au combat.', `name_dede` = '|cffffd100Tipp:|r Erfüllt man die Kriterien für bestimmte Erfolge, so besteht die Möglichkeit, mit einem Gegenstand belohnt zu werden, der einzigartig und nicht für den Kampf gedacht ist.', `name_zhcn` = '|cffffd100小窍门：|r 完成某些成就之后，可以获得特殊的非战斗物品作为奖励。', `name_zhtw` = '|cffffd100小提示:|r完成某些成就可能會得到獨特的非戰鬥物品做為獎勵。', `name_eses` = '|cffffd100Consejo:|r Completar ciertos logros puede otorgarte, como recompensa, objetos únicos que no son para el combate.', `name_esmx` = '|cffffd100Consejo:|r Completar ciertos logros puede otorgarte, como recompensa, objetos únicos que no son para el combate.', `name_ruru` = '|cffffd100Совет:|r За некоторые достижения можно получить уникальные небоевые предметы.' WHERE `id` = 454;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 주문력 효과가 있는 아이템을 착용하면 주문 공격력과 치유 효과가 증가합니다.', `name_frfr` = '|cffffd100Astuce :|r Les objets possédant un bonus à la puissance des sorts augmentent à la fois les effets des sorts de dégâts et de soins.', `name_dede` = '|cffffd100Tipp:|r Gegenstände, die einen Bonus auf Zaubermacht gewähren, erhöhen sowohl den Zauberschaden als auch die Heilung.', `name_zhcn` = '|cffffd100小窍门：|r 具有法术强度加成的物品可以提供法术伤害和治疗加成。', `name_zhtw` = '|cffffd100小提示:|r帶有額外法術能量的物品能同時增強法術傷害和治療效果。', `name_eses` = '|cffffd100Consejo:|r Los objetos con poder con hechizos extra mejoran el daño con hechizos y la sanación.', `name_esmx` = '|cffffd100Consejo:|r Los objetos con poder con hechizos extra mejoran el daño con hechizos y la sanación.', `name_ruru` = '|cffffd100Совет:|r Предметы, увеличивающие силу заклинаний, улучшают как урон от заклинаний, так и эффекты лечения.' WHERE `id` = 455;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 적에게 피해를 주거나 아군을 치유하거나 주문을 시전하면 위협 수준이 생성됩니다. 대부분의 몬스터는 위협 수준이 가장 높은 플레이어를 공격합니다.', `name_frfr` = '|cffffd100Astuce :|r Infliger des dégâts, soigner ou lancer des sorts peut générer de la menace envers une créature. La plupart des créatures attaquent le joueur ayant la plus forte menace envers elles.', `name_dede` = '|cffffd100Tipp:|r Das Verursachen von Schaden, das Wirken von Heilung und Zaubern kann bei einer Kreatur Bedrohung erzeugen. Die meisten Kreaturen werden denjenigen angreifen, der für sie den höchsten Bedrohungswert hat.', `name_zhcn` = '|cffffd100小窍门：|r 造成伤害、进行治疗或施法都会对怪物产生威胁值。大部分怪物会攻击那些对它来说具有最高威胁值的玩家。', `name_zhtw` = '|cffffd100小提示:|r製造傷害、治療或施展法術可能會讓生物產生威脅值。多數的生物會攻擊對他威脅值最高的玩家。', `name_eses` = '|cffffd100Consejo:|r Infligir daño, sanar o lanzar hechizos pueden generar amenaza contra una criatura. La mayoría de las criaturas atacarán al jugador que tenga el nivel de amenaza más alto.', `name_esmx` = '|cffffd100Consejo:|r Infligir daño, sanar o lanzar hechizos pueden generar amenaza contra una criatura. La mayoría de las criaturas atacarán al jugador que tenga el nivel de amenaza más alto.', `name_ruru` = '|cffffd100Совет:|r Нанесение урона, прочтение исцеляющих и защитных заклинаний повышает уровень угрозы существа. Практически все существа нападают на игрока, представляющего для них наибольшую угрозу.' WHERE `id` = 456;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자신보다 4 레벨 이상 높은 몬스터는 자신에게 추가 피해를 주는 강타를 적중시킬 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les créatures de quatre niveaux de plus que vous peuvent vous frapper avec un coup écrasant, qui inflige des dégâts supplémentaires.', `name_dede` = '|cffffd100Tipp:|r Kreaturen, die vier Stufen über Euch sind, können Euch mit einem Schmetterschlag zusätzlichen Schaden zufügen.', `name_zhcn` = '|cffffd100小窍门：|r 等级比你高出四级以上的怪物有可能对你打出碾压攻击，造成额外伤害。', `name_zhtw` = '|cffffd100小提示:|r比你高四級的生物可以在命中時對你使用碾壓，產生額外的傷害。', `name_eses` = '|cffffd100Consejo:|r Las criaturas que te saquen cuatro niveles pueden golpearte con una arremetida machacante que inflige daño extra.', `name_esmx` = '|cffffd100Consejo:|r Las criaturas que te saquen cuatro niveles pueden golpearte con una arremetida machacante que inflige daño extra.', `name_ruru` = '|cffffd100Совет:|r Существа, уровень которых превышает ваш хотя бы на четыре, могут наносить вам сокрушительные удары.' WHERE `id` = 457;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 통계 페이지에서는 캐릭터에 관한 흥미로운 숫자를 볼 수 있습니다. 먹은 음식의 개수나 최대 치명타 및 주문 극대화 적중도 등이 포함됩니다.', `name_frfr` = '|cffffd100Astuce :|r Les statistiques enregistrent certains chiffres intéressants sur votre personnage, comme la quantité de nourriture ingurgitée ou le plus gros coup critique infligé.', `name_dede` = '|cffffd100Tipp:|r In den Statistiken werden einige interessante Daten in Bezug auf Euren Charakter angezeigt, wie zum Beispiel die gesamte Menge an verzehrtem Essen und der höchste kritische Treffer.', `name_zhcn` = '|cffffd100小窍门：|r 统计数据会记录一些与你的角色相关的有趣数据，比如总共吃过的食物数量，或者最高的爆击数字。', `name_zhtw` = '|cffffd100小提示:|r統計頁面記錄著許多關於你角色的有趣數據，譬如說總共吃過多少食物，或最高的致命一擊傷害。', `name_eses` = '|cffffd100Consejo:|r Las estadísticas contienen algunas cifras interesantes relacionadas con tu personaje, como la comida que ha consumido en total o el mayor golpe crítico.', `name_esmx` = '|cffffd100Consejo:|r Las estadísticas contienen algunas cifras interesantes relacionadas con tu personaje, como la comida que ha consumido en total o el mayor golpe crítico.', `name_ruru` = '|cffffd100Совет:|r В статистике можно увидеть некоторые интересные цифры, относящиеся к вашему персонажу – например, количество съеденной пищи и наивысший критический урон.' WHERE `id` = 458;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 여러 도시에 있는 미용실에서 머리 모양이나 색깔을 바꿀 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez vous faire couper et colorer les cheveux dans les salons de coiffure situés dans plusieurs villes.', `name_dede` = '|cffffd100Tipp:|r In vielen Städten gibt es Barbiere, bei denen Ihr Euer Haar schneiden, färben und frisieren lassen könnt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在各大城市中找到理发店，其中提供理发、染发和改变造型等服务。', `name_zhtw` = '|cffffd100小提示:|r你可以在許多城市的美容沙龍中修剪頭髮、改變髮色與造型。', `name_eses` = '|cffffd100Consejo:|r Puedes cortarte el pelo, teñirte o peinarte en una de las peluquerías que hay en las ciudades.', `name_esmx` = '|cffffd100Consejo:|r Puedes cortarte el pelo, teñirte o peinarte en una de las peluquerías que hay en las ciudades.', `name_ruru` = '|cffffd100Совет:|r В парикмахерских, расположенных во многих городах, можно изменить прическу, цвет волос и освежить свой образ новыми аксессуарами!' WHERE `id` = 459;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 친구를 초대하면 게임 상에서 자신과 친구 모두 혜택을 받을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Parrainer un ami dans World of Warcraft vous permet à tous les deux d\'obtenir de belles récompenses.', `name_dede` = '|cffffd100Tipp:|r Werbt Ihr einen Freund für World of Warcraft, könnt Ihr beide eine Belohnung erhalten.', `name_zhcn` = '|cffffd100小窍门：|r 通过战友招募系统和你的朋友一起玩《魔兽世界》，你们两个人都可以获得奖励。', `name_zhtw` = '|cffffd100小提示:|r召集朋友加入魔獸世界能讓你和你的朋友都獲得獎勵。', `name_eses` = '|cffffd100Consejo:|r Reclutar a un amigo para World of Warcraft puede proporcionaros recompensas a los dos.', `name_esmx` = '|cffffd100Consejo:|r Reclutar a un amigo para World of Warcraft puede proporcionaros recompensas a los dos.', `name_ruru` = '|cffffd100Совет:|r Пригласите вашего друга в World of Warcraft – и вы оба получите награду!' WHERE `id` = 460;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 다른 플레이어의 업적을 자신의 업적과 비교해 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez comparer vos hauts faits à ceux d\'un autre joueur.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Eure Erfolge mit denen eines anderen Spielers vergleichen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以和其他的玩家比较各自的成就。', `name_zhtw` = '|cffffd100小提示:|r你可以拿你自己的成就來和其他玩家進行比較。', `name_eses` = '|cffffd100Consejo:|r Puedes comparar tus logros con los de otro jugador.', `name_esmx` = '|cffffd100Consejo:|r Puedes comparar tus logros con los de otro jugador.', `name_ruru` = '|cffffd100Совет:|r Вы можете сравнить свои достижения с достижениями других игроков.' WHERE `id` = 461;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 초상화를 마우스 오른쪽 클릭하여 주시 대상을 설정할 수 있습니다. 주시 대상의 잠금을 해제하면 주시 대상을 원하는 위치로 옮길 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez paramétrer un portrait de focalisation en cliquant droit sur le portrait d\'une unité. Vous pouvez déverrouiller le portrait de focalisation et le placer n\'importe où sur votre écran.', `name_dede` = '|cffffd100Tipp:|r Durch einen Rechtsklick auf die Statusanzeige einer Kreatur oder eines Charakters könnt Ihr ein Fokusziel setzen. Diese Fokusanzeige kann entsperrt und frei auf dem Bildschirm platziert werden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在某个单位的头像上右键点击并设置焦点框体，并且可以解锁该框体，将其在屏幕上任意移动。', `name_zhtw` = '|cffffd100小提示:|r你可以用右鍵點擊一個框架將它設為專注框架。你也可以將專注框架解鎖並移到畫面的任何地方。', `name_eses` = '|cffffd100Consejo:|r Puedes bloquear la posición de un marco haciendo clic derecho sobre el marco de una unidad. Puedes desbloquear el marco y moverlo a donde quieras en la pantalla.', `name_esmx` = '|cffffd100Consejo:|r Puedes bloquear la posición de un marco haciendo clic derecho sobre el marco de una unidad. Puedes desbloquear el marco y moverlo a donde quieras en la pantalla.', `name_ruru` = '|cffffd100Совет:|r Вы можете включить отображение вторичной цели, щелкнув правой кнопкой мыши по ее портрету, и разрешить перемещения окна цели в любое место экрана.' WHERE `id` = 462;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자신에게 시전하는 주문이나 주시 대상에게 시전하는 주문은 인터페이스 설정 - 전투 란에서 따로 설정할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez paramétrer vos options pour lancer des sorts sur vous-même ou sur une cible focalisée dans les options d\'interface de combat.', `name_dede` = '|cffffd100Tipp:|r Durch eine Einstellung im Interfacemenü, Reiter "Kampf", ist es möglich, Zauber automatisch auf sich selbst oder auf ein Fokusziel zu wirken.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过界面设置选项中的“战斗”一栏，为自我施法或焦点目标施法设置快捷键。', `name_zhtw` = '|cffffd100小提示:|r你可以透過介面戰鬥選項，設定對你或你的專注目標施展法術。', `name_eses` = '|cffffd100Consejo:|r Hay una opción para lanzarte hechizos o lanzar hechizos al objetivo marcado en Opciones, Interfaz, Combate.', `name_esmx` = '|cffffd100Consejo:|r Hay una opción para lanzarte hechizos o lanzar hechizos al objetivo marcado en Opciones, Interfaz, Combate.', `name_ruru` = '|cffffd100Совет:|r С помощью параметра «Бой» в меню настройки интерфейса можно переключить направление заклинаний с себя на запомненную цель.' WHERE `id` = 463;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 달력을 이용하여 게임 이벤트를 확인할 수 있고 친구들과 일정을 세울 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez utiliser le calendrier pour visualiser les évènements saisonniers à venir ou pour organiser des évènements avec votre guilde ou vos amis.', `name_dede` = '|cffffd100Tipp:|r Der Kalender kann genutzt werden, um verschiedene Ereignisse mit Gildenmitgliedern und Freunden zu planen. Zudem sind anstehende Feiertage darin vermerkt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用日历系统查看即将到来的节日，以及公会和好友的活动计划。', `name_zhtw` = '|cffffd100小提示:|r你可以利用行事曆查詢即將到來的節日，或者安排與公會或朋友一同進行的活動。', `name_eses` = '|cffffd100Consejo:|r Utiliza el Calendario para ver las próximas fiestas o para organizar eventos con tu hermandad o tus amigos.', `name_esmx` = '|cffffd100Consejo:|r Utiliza el Calendario para ver las próximas fiestas o para organizar eventos con tu hermandad o tus amigos.', `name_ruru` = '|cffffd100Совет:|r В календаре можно увидеть грядущие праздники и запланировать события с членами гильдии или друзьями.' WHERE `id` = 464;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 시계를 마우스 오른쪽 클릭하면 경보를 설정하거나 초시계를 불러올 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez cliquer droit sur l\'horloge pour paramétrer une alarme ou afficher un chronomètre.', `name_dede` = '|cffffd100Tipp:|r Ein Rechtsklick auf die Uhr öffnet ein Menü für Alarmeinstellungen und die Stoppuhr.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过右键点击时钟来设置提醒时间或显示秒表。', `name_zhtw` = '|cffffd100小提示:|r你可以用右鍵點擊時鐘，以設定鬧鐘或顯示碼錶。', `name_eses` = '|cffffd100Consejo:|r Si pulsas el botón derecho sobre el Reloj, podrás poner la alarma o mostrar el cronómetro.', `name_esmx` = '|cffffd100Consejo:|r Si pulsas el botón derecho sobre el Reloj, podrás poner la alarma o mostrar el cronómetro.', `name_ruru` = '|cffffd100Совет:|r Чтобы установить будильник или показать секундомер, щелкните правой кнопкой мыши по часам.' WHERE `id` = 465;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 주문각인 기술을 배운 플레이어는 주문에 문양을 새겨 즐겨 사용하는 주문이나 능력을 강화시킬 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les personnages ayant pour profession la calligraphie peuvent créer des glyphes qui améliorent certains de vos sorts et techniques favoris.', `name_dede` = '|cffffd100Tipp:|r Charaktere mit dem Beruf der Inschriftenkunde können Glyphen erschaffen, mit denen einige Eurer bevorzugten Zauber und Fähigkeiten unterstützt werden können.', `name_zhcn` = '|cffffd100小窍门：|r 学习了铭文专业的角色可以制作铭文，用以强化你所偏好的法术和技能。', `name_zhtw` = '|cffffd100小提示:|r具有銘文學專業技能的角色可銘刻雕紋來強化自己偏好的法術與技能。', `name_eses` = '|cffffd100Consejo:|r Los personajes con la profesión Inscripción pueden inscribir glifos para mejorar algunos de tus hechizos y habilidades preferidos.', `name_esmx` = '|cffffd100Consejo:|r Los personajes con la profesión Inscripción pueden inscribir glifos para mejorar algunos de tus hechizos y habilidades preferidos.', `name_ruru` = '|cffffd100Совет:|r Изучив профессию «Начертание», вы сможете рисовать символы, улучшающие характеристики заклинаний и способностей.' WHERE `id` = 466;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 무언가 색다른 일을 하고 싶다면 특이한 업적을 찾아 시도해 보십시오.', `name_frfr` = '|cffffd100Astuce :|r Si vous souhaitez faire quelque chose de différent, tentez d\'accomplir des hauts faits inhabituels.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr mal etwas ganz anderes ausprobieren wollt, versucht doch einmal, einen der ungewöhnlicheren Erfolge zu erreichen.', `name_zhcn` = '|cffffd100小窍门：|r 如果你想要找一些特别的事情做，可以尝试完成一些不寻常的成就。', `name_zhtw` = '|cffffd100小提示:|r如果你想找些別的事情來做，試試看完成一些不尋常的成就吧。', `name_eses` = '|cffffd100Consejo:|r Si buscas algo diferente que hacer, prueba a realizar algunos de los logros menos comunes.', `name_esmx` = '|cffffd100Consejo:|r Si buscas algo diferente que hacer, prueba a realizar algunos de los logros menos comunes.', `name_ruru` = '|cffffd100Совет:|r Если вы хотите отвлечься от привычного течения игры, попробуйте заслужить некоторые необычные достижения.' WHERE `id` = 467;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r Shift키를 누른 상태에서 마우스 왼쪽 버튼을 클릭하면 퀘스트, 아이템, 주문, 업적을 대화 창에 링크시킬 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez faire un lien dans vos messages de discussion vers des quêtes, des objets, des sorts et des hauts faits, en faisant Maj+clic gauche sur les éléments appropriés.', `name_dede` = '|cffffd100Tipp:|r Links zu Quests, Gegenständen, Zaubern und Erfolgen können durch Rechtsklick in den Chat eingefügt werden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过按住Shift点击的方式，在聊天信息中链接任务、物品、法术和成就。', `name_zhtw` = '|cffffd100小提示:|r你可以使用Shift+左鍵點擊記錄中的任務、物品、法術與成就，將其連結至對話頻道中。', `name_eses` = '|cffffd100Consejo:|r Puedes introducir las misiones, los objetos, los hechizos y los logros en los mensajes del chat haciendo clic izquierdo y pulsando <Mayús> en tu registro.', `name_esmx` = '|cffffd100Consejo:|r Puedes introducir las misiones, los objetos, los hechizos y los logros en los mensajes del chat haciendo clic izquierdo y pulsando <Mayús> en tu registro.', `name_ruru` = '|cffffd100Совет:|r Чтобы создать в сообщении ссылку на задание, предмет, заклинание или достижение, щелкните по нему левой кнопкой мыши в журнале при зажатой клавише Shift.' WHERE `id` = 468;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 진행 중인 퀘스트나 업적은 추적 기능이 지원됩니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez suivre la progression de vos quêtes et de vos hauts faits en cours de réalisation.', `name_dede` = '|cffffd100Tipp:|r Es ist möglich, den Fortschritt von Quests und Erfolgen zu verfolgen.', `name_zhcn` = '|cffffd100小窍门：|r 你可以追踪当前任务或成就的进展。', `name_zhtw` = '|cffffd100小提示:|r你可以追蹤目前任務或成就的進度。', `name_eses` = '|cffffd100Consejo:|r Puedes ver el progreso de tus misiones actuales o de tus logros.', `name_esmx` = '|cffffd100Consejo:|r Puedes ver el progreso de tus misiones actuales o de tus logros.', `name_ruru` = '|cffffd100Совет:|r Вы можете отслеживать состояние текущих заданий и достижений.' WHERE `id` = 469;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 미니맵에 있는 돋보기를 클릭하면 저레벨 퀘스트나 상인 등 여러 종류의 대상을 추적할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez afficher de nombreuses choses, comme les quêtes de bas-niveau ou les vendeurs, en cliquant sur la loupe près de votre mini-carte.', `name_dede` = '|cffffd100Tipp:|r Durch einen Klick auf das Vergrößerungsglas an der Minikarte öffnet sich die Fährtensuche, die vielseitig eingesetzt werden kann - auch zum Beispiel, um niedrigstufige Quests oder spezielle Händler zu finden.', `name_zhcn` = '|cffffd100小窍门：|r 你可以通过点击微缩地图旁边的放大镜图标来追踪很多东西，比如低等级任务或各类商人。', `name_zhtw` = '|cffffd100小提示:|r你可以透過點擊小地圖旁邊的放大鏡追蹤許多東西，譬如說低等級任務或商人。', `name_eses` = '|cffffd100Consejo:|r Si utilizas la lupa junto al minimapa, podrás ver muchas cosas como misiones de nivel bajo o vendedores.', `name_esmx` = '|cffffd100Consejo:|r Si utilizas la lupa junto al minimapa, podrás ver muchas cosas como misiones de nivel bajo o vendedores.', `name_ruru` = '|cffffd100Совет:|r Радар в виде лупы на миникарте позволяет видеть местонахождение узкоспециализированных продавцов, персонажей, дающих задания низкого уровня, и многое другое.' WHERE `id` = 470;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 샤트라스나 달라란 등의 성역은 플레이어 간 분쟁이 금지되는 지역입니다.', `name_frfr` = '|cffffd100Astuce :|r Un sanctuaire est une ville où les combats JcJ ne sont pas autorisés, comme Shattrath et Dalaran.', `name_dede` = '|cffffd100Tipp:|r Eine Zuflucht ist eine Stadt, in der kein Kampf \'Spieler gegen Spieler\' möglich ist, wie Shattrath und Dalaran.', `name_zhcn` = '|cffffd100小窍门：|r 安全区域是指禁止进行PvP（玩家对玩家）战斗的城镇，比如沙塔斯和达拉然。', `name_zhtw` = '|cffffd100小提示:|r聖域是禁止玩家對玩家戰鬥的城鎮，像是撒塔斯和達拉然。', `name_eses` = '|cffffd100Consejo:|r Un santuario es una ciudad en la que los combates Jugador contra Jugador están prohibidos, como Shattrath y Dalaran.', `name_esmx` = '|cffffd100Consejo:|r Un santuario es una ciudad en la que los combates Jugador contra Jugador están prohibidos, como Shattrath y Dalaran.', `name_ruru` = '|cffffd100Совет:|r Святилище – это город, в котором запрещены сражения между игроками: например, Шаттрат и Даларан.' WHERE `id` = 471;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 특정 진영에 대한 평판을 올리면 새로운 퀘스트를 받거나 아이템을 얻을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Améliorer votre réputation auprès de diverses factions vous permet d\'accéder à de nouvelles quêtes et récompenses.', `name_dede` = '|cffffd100Tipp:|r Wenn Ihr Euren Ruf bei einer Fraktion erhöht, könnt Ihr Zugang zu neuen Quests und Gegenständen erlangen.', `name_zhcn` = '|cffffd100小窍门：|r 提高你在某一阵营中的声望，就可以获得新的任务或物品。', `name_zhtw` = '|cffffd100小提示:|r提高你在某個勢力的聲望可以獲得新的任務與物品。', `name_eses` = '|cffffd100Consejo:|r Si mejoras tu reputación con una facción, puede que tengas acceso a nuevas misiones u objetos.', `name_esmx` = '|cffffd100Consejo:|r Si mejoras tu reputación con una facción, puede que tengas acceso a nuevas misiones u objetos.', `name_ruru` = '|cffffd100Совет:|r Улучшив отношения с фракцией, вы можете получить новые задания или товары у ее представителей.' WHERE `id` = 472;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 달력으로 공격대 초기화 일정을 확인할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Le calendrier vous apprend quand vos raids sont remis à zéro.', `name_dede` = '|cffffd100Tipp:|r Der Kalender kann Auskunft darüber geben, wann Schlachtzugsinstanzen zurückgesetzt werden.', `name_zhcn` = '|cffffd100小窍门：|r 日历系统可以告诉你团队副本何时重置。', `name_zhtw` = '|cffffd100小提示:|r行事曆可以告訴你團隊副本重置的時間。', `name_eses` = '|cffffd100Consejo:|r El Calendario puede decirte cuándo se reinician las bandas.', `name_esmx` = '|cffffd100Consejo:|r El Calendario puede decirte cuándo se reinician las bandas.', `name_ruru` = '|cffffd100Совет:|r В календаре отображается время сброса сохраненных рейдов.' WHERE `id` = 473;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 몬스터의 주문 공격은 극대화 효과가 없습니다. 플레이어의 주문만이 극대화 효과를 발휘할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les créatures ne peuvent pas infliger de coups critiques avec les sorts, contrairement aux joueurs.', `name_dede` = '|cffffd100Tipp:|r Kreaturen können keine kritischen Zaubertreffer erzielen, Spieler hingegen schon.', `name_zhcn` = '|cffffd100小窍门：|r 怪物的法术不会打出爆击，但玩家的法术可以爆击。', `name_zhtw` = '|cffffd100小提示:|r非玩家角色無法用法術發出致命一擊，但玩家可以。', `name_eses` = '|cffffd100Consejo:|r Las criaturas no pueden realizar golpes críticos con sus hechizos, pero los jugadores sí.', `name_esmx` = '|cffffd100Consejo:|r Las criaturas no pueden realizar golpes críticos con sus hechizos, pero los jugadores sí.', `name_ruru` = '|cffffd100Совет:|r В отличие от игроков, существа не могут наносить критический урон заклинаниями.' WHERE `id` = 474;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 몬스터는 후방에서 가해지는 공격을 회피할 수 있지만 플레이어는 회피하지 못합니다. 몬스터와 플레이어 모두 후방에서 가해지는 공격을 무기로 막지 못합니다.', `name_frfr` = '|cffffd100Astuce :|r Les créatures peuvent esquiver les attaques dans le dos, mais pas les joueurs. Ni les créatures, ni les joueurs ne peuvent parer les attaques dans le dos.', `name_dede` = '|cffffd100Tipp:|r Kreaturen können Angriffen von hinten ausweichen, Spieler können es jedoch nicht. Weder Kreaturen noch Spieler können Angriffe von hinten parieren.', `name_zhcn` = '|cffffd100小窍门：|r 怪物可以躲闪来自后方的攻击，但是玩家不行。怪物和玩家都不能招架来自后方的攻击。', `name_zhtw` = '|cffffd100小提示:|r非玩家角色可以閃躲來自後方的攻擊，但玩家則不行。而玩家與非玩家角色都不可以招架來自後方的攻擊。', `name_eses` = '|cffffd100Consejo:|r Las criaturas pueden esquivar ataques por la espalda, pero los jugadores no. Ni las criaturas ni los jugadores pueden parar ataques por la espalda.', `name_esmx` = '|cffffd100Consejo:|r Las criaturas pueden esquivar ataques por la espalda, pero los jugadores no. Ni las criaturas ni los jugadores pueden parar ataques por la espalda.', `name_ruru` = '|cffffd100Совет:|r В отличие от игроков, существа могут уклоняться от атак сзади. Ни те, ни другие не могут парировать атаки со спины.' WHERE `id` = 475;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r V키를 누르면 적의 머리 위에 이름표를 표시합니다. 이름표를 활성화시키면 적의 생명력과 주문 시전 상태를 볼 수 있고 대상을 빠르게 바꾸는 데도 도움이 됩니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez utiliser la touche V pour montrer les informations essentielles concernant votre ennemi au-dessus de sa tête. Vous pouvez ainsi voir la vie de votre ennemi et les sorts qu\'il lance. Cela vous permet également de changer plus facilement de cible.', `name_dede` = '|cffffd100Tipp:|r Die Taste V kann genutzt werden, um Namensplaketten über den Köpfen der Gegner anzuzeigen. Namensplaketten können helfen, sowohl die Gesundheit von Gegnern besser zu verfolgen, als auch ihre gewirkten Zauber. Sie können auch dabei helfen, schnell das Ziel zu wechseln.', `name_zhcn` = '|cffffd100小窍门：|r 你可以使用V键在敌人的头顶上显示其姓名板，并通过姓名板观察敌人的生命值和施法条，还可以快速切换目标。', `name_zhtw` = '|cffffd100小提示:|r按下V鍵可以顯示敵人頭上的名條。名條可以讓你追蹤敵人的生命力和施法狀況，或讓你可以快速更換目標。', `name_eses` = '|cffffd100Consejo:|r Puedes utilizar la tecla V para mostrar el nombre de tu enemigo sobre su cabeza. Puede que esto te ayude a hacer un seguimiento de la vida del enemigo o del lanzamiento de hechizos, o incluso puede facilitar el cambio de objetivos.', `name_esmx` = '|cffffd100Consejo:|r Puedes utilizar la tecla V para mostrar el nombre de tu enemigo sobre su cabeza. Puede que esto te ayude a hacer un seguimiento de la vida del enemigo o del lanzamiento de hechizos, o incluso puede facilitar el cambio de objetivos.', `name_ruru` = '|cffffd100Совет:|r С помощью клавиши \'V\' можно включить отображение индикаторов над головой врагов. Индикаторы показывают количество здоровья противника, наложенные на него отрицательные эффекты, а также помогают более эффективно переключаться между целями.' WHERE `id` = 476;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 설정에 있는 장비 관리창 기능을 활성화하여 자주 사용하는 장비 구성을 빠르게 바꿀 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez activer le Gestionnaire d\'équipement dans l\'écran d\'interface pour échanger rapidement des tenues et des armes que vous utilisez souvent.', `name_dede` = '|cffffd100Tipp:|r In der Interface-Steuerung kann der Ausrüstungsmanager aktiviert werden, der Euch schnell zwischen verschiedenen Ausrüstungssets umschalten lässt, die Ihr häufig nutzt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在界面控制选项中启用装备功能，迅速在你常用的多种装备组合方案中进行切换。', `name_zhtw` = '|cffffd100小提示:|r你能夠在介面控制選項中開啟裝備管理員功能以便讓你快速切換你常使用的裝備。', `name_eses` = '|cffffd100Consejo:|r Puedes activar el Gestor de equipo desde Controles de Interfaz para cambiar rápidamente entre conjuntos de equipo que utilices con frecuencia.', `name_esmx` = '|cffffd100Consejo:|r Puedes activar el Gestor de equipo desde Controles de Interfaz para cambiar rápidamente entre conjuntos de equipo que utilices con frecuencia.', `name_ruru` = '|cffffd100Совет:|r Вы можете активировать функцию управления экипировкой в настройках интерфейса, чтобы быстро переключаться между часто используемыми комплектами обмундирования.' WHERE `id` = 479;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 40 레벨에 도달하면 직업 상급자를 통해 이중 특성을 습득할 수 있습니다. 이중 특성은 자주 사용하는 특성, 문양, 행동 단축바의 두 가지 설정을 상호 전환할 수 있도록 도와주는 기능입니다.', `name_frfr` = '|cffffd100Astuce :|r Quand vous atteignez le niveau 40, votre maître de classe peut vous apprendre la double spécialisation des talents. Elle vous permet de changer rapidement vos talents, vos glyphes et vos barres d\'actions entre deux configurations que vous utilisez souvent.', `name_dede` = '|cffffd100Tipp:|r Sobald Ihr Stufe 40 erreicht, kann Euch der Lehrer für Eure Klasse in der dualen Talentspezialisierung unterweisen. Durch sie ist es möglich, zwischen zwei häufig genutzten Konfigurationen Eurer Talente, Glyphen und Aktionsleisten umzuschalten.', `name_zhcn` = '|cffffd100小窍门：|r 当你达到40级之后，可以到职业训练师那里去开启双天赋界面。这个功能可以让你配置两套常用的天赋、雕文和动作条，并且可以随需要进行切换。', `name_zhtw` = '|cffffd100小提示:|r當你到達40級時，可以從職業訓練師處習得雙天賦專精。這個功能允許你切換兩組常用的天賦、雕紋及快捷列設定。', `name_eses` = '|cffffd100Consejo:|r Cuando llegues al nivel 40 tu instructor de clase puede enseñarte la doble especialización de talentos. Esta característica te permite intercambiar entre las dos configuraciones de talentos, glifos y barras de acción que más uses.', `name_esmx` = '|cffffd100Consejo:|r Cuando llegues al nivel 40 tu instructor de clase puede enseñarte la doble especialización de talentos. Esta característica te permite intercambiar entre las dos configuraciones de talentos, glifos y barras de acción que más uses.', `name_ruru` = '|cffffd100Совет:|r Достигнув 40-го уровня, вы можете обучиться двойной специализации у наставника своего класса. Это позволит вам переключаться между двумя раскладками талантов, символов и панелей команд.' WHERE `id` = 480;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 투기장 상대 플레이어창을 사용하면 투기장에서 경기를 치를 때 상대팀의 플레이어창을 표시할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez activer l\'option Portraits d\'ennemis en arène pour afficher les portraits des membres de l\'équipe ennemie dans les matchs d\'arène.', `name_dede` = '|cffffd100Tipp:|r Damit in der Arena Portraits und Lebensbalken des gesamten gegnerischen Teams angezeigt werden, könnt Ihr in der Interface-Steuerung die Option \'Gegneranzeige in Arena\' aktivieren.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在竞技场比赛中使用竞技场对手框体功能，显示对手的单位框体。', `name_zhtw` = '|cffffd100小提示:|r在競技場戰鬥中能夠開啟競技場敵方框架來顯示敵隊的單位框架。', `name_eses` = '|cffffd100Consejo:|r Mientras estás en una partida de arena puedes activar los Marcos enemigos de arena para mostrar los marcos de las unidades enemigas.', `name_esmx` = '|cffffd100Consejo:|r Mientras estás en una partida de arena puedes activar los Marcos enemigos de arena para mostrar los marcos de las unidades enemigas.', `name_ruru` = '|cffffd100Совет:|r Вы можете настроить отображение рамок команды противника на арене, чтобы видеть портреты противников во время боя.' WHERE `id` = 481;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 인터페이스 설정에서 특성 변경 미리 보기 옵션을 선택하면, 특성 변경 사항을 저장하기 전에 다양한 방법으로 특성 포인트를 사용해 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Dans les options d\'affichage de l\'interface, vous pouvez activer l\'Aperçu des modifications de talents. Si vous activez cette option, vous pourrez essayer différentes façons de dépenser vos points de talent avant de sauvegarder vos modifications.', `name_dede` = '|cffffd100Tipp:|r Im Interfacemenü befindet sich eine Option, durch welche die Vorschau von Talentänderungen aktiviert werden kann. Wenn Ihr diese Option aktiviert, könnt Ihr verschiedenste Arten der Talentpunkteverteilung ausprobieren, bevor Ihr die Änderungen speichert.', `name_zhcn` = '|cffffd100小窍门：|r 界面显示设置中有预览天赋改变的选项。如果你启用了这个功能，就可以在实际花费天赋点数之前尝试各种配置方案。', `name_zhtw` = '|cffffd100小提示:|r在介面設定的顯示中有一個預覽天賦變更的選項。如果你勾選該選項，在儲存變更後的天賦前能夠自由的修正你的天賦配置。', `name_eses` = '|cffffd100Consejo:|r En la sección Pantalla de Interfaz encontrarás la Vista previa de talentos. Si seleccionas esta opción, podrás ir probando diferentes maneras de gastar puntos de talento antes de guardar los cambios.', `name_esmx` = '|cffffd100Consejo:|r En la sección Pantalla de Interfaz encontrarás la Vista previa de talentos. Si seleccionas esta opción, podrás ir probando diferentes maneras de gastar puntos de talento antes de guardar los cambios.', `name_ruru` = '|cffffd100Совет:|r В настройках интерфейса есть возможность включить предварительный просмотр талантов. Эта функция позволяет испробовать различные варианты распределения очков талантов перед сохранением изменений.' WHERE `id` = 482;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자신의 캐릭터에 있는 아이템 칸에 마우스 커서를 올리고 Alt 키를 누르면, 해당 칸에 착용할 수 있는 아이템 목록을 확인할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Si vous appuyez sur « Alt » lorsque le curseur est sur un emplacement d’objet dans votre feuille de personnage, vous verrez apparaître une liste d’objets dont vous pouvez vous équiper à cet emplacement.', `name_dede` = '|cffffd100Tipp:|r Wenn sich der Mauszeiger über einem Gegenstandsplatz in Eurem Charakterfenster befindet, wird bei gedrückter Alt-Taste eine Liste von Gegenständen angezeigt, die an diesem Platz ausgerüstet werden können.', `name_zhcn` = '|cffffd100小窍门：|r 如果你将鼠标指针放在角色界面中的某个装备栏上，并按住Alt键，就可以看到背包中所有可以装备在该栏位的物品的列表。', `name_zhtw` = '|cffffd100小提示:|r當你按下Alt鍵並將游標移到角色身上的某個欄位時，將會產生一份此欄位能夠裝備的物品清單。', `name_eses` = '|cffffd100Consejo:|r Si presionas ALT cuando tu cursor está sobre una casilla de objeto de tu personaje, puedes sacar una lista de objetos que se pueden equipar en esa casilla.', `name_esmx` = '|cffffd100Consejo:|r Si presionas ALT cuando tu cursor está sobre una casilla de objeto de tu personaje, puedes sacar una lista de objetos que se pueden equipar en esa casilla.', `name_ruru` = '|cffffd100Совет:|r Если нажать клавишу Alt, наведя указатель мыши на ячейку в окне персонажа, появится список вещей, которые можно поместить в эту ячейку.' WHERE `id` = 483;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 적의 주문 시전바 주위에 방패 아이콘이 있으면 해당 주문은 방해할 수 없습니다.', `name_frfr` = '|cffffd100Astuce :|r Si la barre de sorts d’un ennemi est entourée d’une icône de bouclier, vous ne pouvez pas interrompre ce sort à l’aide de vos capacités.', `name_dede` = '|cffffd100Tipp:|r Wenn ein feindlicher Zauberbalken von einem Schildsymbol umgeben ist, kann dieser Zauber durch Eure Fähigkeiten nicht unterbochen werden.', `name_zhcn` = '|cffffd100小窍门：|r 如果敌人的施法条旁有一个护盾图标，则代表你无法打断该法术。', `name_zhtw` = '|cffffd100小提示:|r如果敵人的施法條上有一個盾牌圖示，那表示你無法使用你的技能來中斷該法術。', `name_eses` = '|cffffd100Consejo:|r Si la barra de lanzamiento de un enemigo tiene el icono de un escudo alrededor, quiere decir que no puedes interrumpir el hechizo con tus facultades.', `name_esmx` = '|cffffd100Consejo:|r Si la barra de lanzamiento de un enemigo tiene el icono de un escudo alrededor, quiere decir que no puedes interrumpir el hechizo con tus facultades.', `name_ruru` = '|cffffd100Совет:|r Если полоска заклинания противника отмечена знаком щита, вы не сможете прервать его прочтение своими способностями.' WHERE `id` = 489;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 길드에서는 게임 내 달력을 사용하여 길드 일정을 계획할 수 있습니다. 초대가 올 때까지 기다리지 말고 여러분의 길드 일정에 직접 참가 신청을 해보세요.', `name_frfr` = '|cffffd100Astuce :|r Votre guilde peut prévoir des Évènements de guilde à l’aide du calendrier en jeu. Vous pouvez choisir de vous y inscrire plutôt que d’attendre une invitation.', `name_dede` = '|cffffd100Tipp:|r Eure Gilde kann mittels des Kalenders im Spiel Gildenereignisse erstellen. Für diese Ereignisse könnt Ihr Euch einschreiben und müsst nicht auf eine Einladung warten.', `name_zhcn` = '|cffffd100小窍门：|r公会管理者可以使用游戏内的日历来设定公会日程。你可以自主报名而不用再等候邀请。', `name_zhtw` = '|cffffd100小提示:|r你的公會可以利用遊戲內的行事曆來規劃公會活動。你可以主動報名來參加這些活動，而不用等待主辦者的邀請。', `name_eses` = '|cffffd100Consejo:|r Tu hermandad puede planear eventos de hermandad usando el calendario del juego. Tú puedes decidir apuntarte a estos eventos, en vez de esperar una invitación.', `name_esmx` = '|cffffd100Consejo:|r Tu hermandad puede planear eventos de hermandad usando el calendario del juego. Tú puedes decidir apuntarte a estos eventos, en vez de esperar una invitación.', `name_ruru` = '|cffffd100Совет:|rГильдия может планировать события, пользуясь игровым календарем. Вы можете подписываться на события сами, а не ждать приглашения.' WHERE `id` = 490;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 자동 완성 기능을 통해 캐릭터 이름이 완성되면 Tab 또는 <Shift> Tab 키를 눌러 목록에서 이름을 선택할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Lorsque la fonctionnalité de remplissage automatique suggère des noms de personnages, appuyez sur Tab. ou Maj. + Tab. pour sélectionner un nom dans la liste.', `name_dede` = '|cffffd100Tipp:|r Wenn die automatische Vervollständigung einen Namen vorschlägt, kann die Tab-Taste oder Tab + Umschalttaste gedrückt werden, um einen Namen von der Liste auszuwählen.', `name_zhcn` = '|cffffd100小窍门：|r 您可以使用Tab键或是Shift+Tab来从自动起名列表中选取中意的名字。', `name_zhtw` = '|cffffd100小提示:|r當自動填名功能產生角色名稱的推薦清單時，你可以使用Tab鍵或Shift+Tab鍵來選擇清單中的名稱。', `name_eses` = '|cffffd100Consejo:|r Cuando la opción de autocompletar sugiera nombres de personaje, puedes usar el Tabulador o <Mayús> Tabulador para seleccionar un nombre de la lista.', `name_esmx` = '|cffffd100Consejo:|r Cuando la opción de autocompletar sugiera nombres de personaje, puedes usar el Tabulador o <Mayús> Tabulador para seleccionar un nombre de la lista.', `name_ruru` = '|cffffd100Совет:|r Когда функция автозаполнения предлагает вам имена персонажей, вы можете выбрать имя в списке с помощью клавиш Tab или Shift + Tab.' WHERE `id` = 491;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 계정 정보를 입력할 때는 해당 사이트가 블리자드 공식 웹사이트인지 다시 한 번 확인하세요.', `name_frfr` = '|cffffd100Astuce :|r Vérifiez toujours que vous êtes sur un site officiel de Blizzard lorsque vous indiquez vos informations de compte.', `name_dede` = '|cffffd100Tipp:|r Stellen Sie immer sicher, dass Sie auf eine offizielle Webseite von Blizzard zugreifen, wenn Sie Account-Informationen übermitteln.', `name_zhcn` = '|cffffd100小窍门：|r当您提交帐号信息的时候，请一定先确认自己登录是暴雪娱乐的官方网站。', `name_zhtw` = '|cffffd100Tip:|r當您輸入帳號資料時，請確認您登錄的是暴雪的官方網站。', `name_eses` = '|cffffd100Consejo:|r Asegúrate siempre de que estás accediendo a un sitio web oficial de Blizzard antes de enviar información de tu cuenta.', `name_esmx` = '|cffffd100Consejo:|r Asegúrate siempre de que estás accediendo a un sitio web oficial de Blizzard antes de enviar información de tu cuenta.', `name_ruru` = '|cffffd100Совет:|r Убедитесь, что вы находитесь на официальном сайте Blizzard, прежде чем указывать данные своей учетной записи.' WHERE `id` = 500;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 블리자드에서 발송된 이메일은 마지막에 blizzard.co.kr 또는 battle.net이 표기되어 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les emails envoyés par Blizzard proviennent toujours d\'une adresse se terminant par blizzard.com ou battle.net.', `name_dede` = '|cffffd100Tipp:|r E-Mails von Blizzard werden immer auf blizzard.com oder battle.net enden.', `name_zhcn` = '|cffffd100小窍门：|r暴雪娱乐发出的电子邮件一定会以“blizzard.com”或”battle.net”结尾。', `name_zhtw` = '|cffffd100Tip:|r暴雪的電子郵件都會由blizzard.com或battle.net寄出。', `name_eses` = '|cffffd100Consejo:|r Los correos enviados por Blizzard siempre terminan en "blizzard.com" o en "battle.net".', `name_esmx` = '|cffffd100Consejo:|r Los correos enviados por Blizzard siempre terminan en "blizzard.com" o en "battle.net".', `name_ruru` = '|cffffd100Совет:|r Обратный адрес электронных писем от компании Blizzard всегда заканчивается на blizzard.com или battle.net.' WHERE `id` = 501;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 컴퓨터에 키로거를 비롯한 악성 소프트웨어가 설치되어 있지는 않은지, 무료 프로그램을 다운로드하여 정기적으로 검사하세요.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez télécharger des programmes gratuits qui analysent régulièrement votre machine à la recherche de logiciels malveillants, y compris les « keyloggers ».', `name_dede` = '|cffffd100Tipp:|r Sie können kostenlose Programme herunterladen, um Ihren Rechner regelmäßig auf bösartige Software und Keylogger zu prüfen.', `name_zhcn` = '|cffffd100小窍门：|r您可以通过下载免费软件来定期扫描您的电脑，寻找并清除包括键盘记录程序在内的恶意软件。', `name_zhtw` = '|cffffd100Tip:|r你可以下載免費的軟體定期掃瞄你的電腦，尋找可能危害你的惡意程式，例如內含鍵盤側錄功能的程式。', `name_eses` = '|cffffd100Consejo:|r Puedes descargar programas gratuitos para que analicen de manera frecuente tu ordenador en busca de software malicioso, incluidos los keyloggers.', `name_esmx` = '|cffffd100Consejo:|r Puedes descargar programas gratuitos para que analicen de manera frecuente tu ordenador en busca de software malicioso, incluidos los keyloggers.', `name_ruru` = '|cffffd100Совет:|r Для защиты от вредоносных программ и клавиатурных шпионов вы можете бесплатно скачать соответствующие утилиты и периодически выполнять проверку вашего компьютера.' WHERE `id` = 502;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 월드 오브 워크래프트 계정을 블리자드 Battle.net 계정으로 통합하여 새로운 기능들을 편리하게 이용하세요.', `name_frfr` = '|cffffd100Astuce :|r Pour accéder à des fonctionnalités avancées, fusionnez votre compte World of Warcraft et votre compte Blizzard Battle.net.', `name_dede` = '|cffffd100Tipp:|r Indem Sie Ihren "World of Warcraft"-Account in einen "Battle.net"-Account umwandeln, erhalten Sie Zugang zu weiteren Features und Funktionalitäten.', `name_zhcn` = '|cffffd100小窍门：|r请将您的魔兽世界帐号绑定到暴雪战网帐号中，以便享受暴雪战网的新增功能与服务。', `name_zhtw` = '|cffffd100小提示:|r當你按下Alt鍵並將游標移到角色身上的某個欄位時，將會產生一份此欄位能夠裝備的物品清單。', `name_eses` = '|cffffd100Consejo:|r Para disponer de mayores opciones y funcionalidad, fusiona tu cuenta de World of Warcraft con una cuenta de Battle.net.', `name_esmx` = '|cffffd100Consejo:|r Para disponer de mayores opciones y funcionalidad, fusiona tu cuenta de World of Warcraft con una cuenta de Battle.net.', `name_ruru` = '|cffffd100Совет:|r Чтобы получить доступ к дополнительным функциям и возможностям, объедините учетную запись World of Warcraft с учетной записью Blizzard Battle.net.' WHERE `id` = 503;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 블리자드 인증기 또는 Battle.net 모바일 인증기를 사용하면 계정 도용으로부터 여러분의 월드 오브 워크래프트 계정을 보호할 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Utiliser un Blizzard Authenticator ou un Battle.net Mobile Authenticator vous aidera à protéger votre compte World of Warcraft des vols.', `name_dede` = '|cffffd100Tipp:|r Die Nutzung eines Blizzard Authenticators oder Battle.net Mobile Authenticators hilft, Ihren "World of Warcraft"-Account vor Diebstahl zu schützen.', `name_zhcn` = '|cffffd100小窍门：|r使用密保卡或是将军令会保护您的魔兽世界帐号安全。', `name_zhtw` = '|cffffd100小提示:|r如果敵人的施法條上有一個盾牌圖示，那表示你無法使用你的技能來中斷該法術。', `name_eses` = '|cffffd100Consejo:|r Si usas un Blizzard Authenticator o un Battle.net Mobile Authenticator ayudarás a proteger tu cuenta de World of Warcraft de robos.', `name_esmx` = '|cffffd100Consejo:|r Si usas un Blizzard Authenticator o un Battle.net Mobile Authenticator ayudarás a proteger tu cuenta de World of Warcraft de robos.', `name_ruru` = '|cffffd100Совет:|r Использование брелка Blizzard Authenticator и его электронной версии Battle.net Mobile Authenticator поможет защитить учетную запись World of Warcraft от кражи.' WHERE `id` = 504;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 여러 사람이 사용하는 컴퓨터에는 악성 소프트웨어가 설치되어 있을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Pour éviter qu\'on vous vole votre compte, ne vous connectez pas à World of Warcraft depuis un ordinateur public. Ces ordinateurs peuvent être infectés par des logiciels malveillants.', `name_dede` = '|cffffd100Tipp:|r Um Account-Diebstahl zu verhindern, vermeiden Sie es, sich auf öffentlichen Computern in "World of Warcraft" einzuloggen. Diese Rechner können mit bösartiger Software infiziert sein.', `name_zhcn` = '|cffffd100小窍门：|r为了防止帐号被盗，请不要在公共电脑上登录魔兽世界。此类电脑很有可能已经被恶意软件感染。', `name_zhtw` = '|cffffd100Tip:|r為防止帳號盜用，請不要在公共場所的電腦上登入魔獸世界。這些電腦可能已經感染了惡意程式。', `name_eses` = '|cffffd100Consejo:|r Para evitar el robo de tu cuenta, no inicies sesión en World of Warcraft con un ordenador de uso público. Estos ordenadores podrían contener software malicioso.', `name_esmx` = '|cffffd100Consejo:|r Para evitar el robo de tu cuenta, no inicies sesión en World of Warcraft con un ordenador de uso público. Estos ordenadores podrían contener software malicioso.', `name_ruru` = '|cffffd100Совет:|r Чтобы избежать кражи учетной записи, не авторизуйтесь в World of Warcraft на компьютерах с общественным доступом, так как они могут быть заражены вредоносными программами.' WHERE `id` = 505;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 공식 사이트가 아닌 곳에서 월드 오브 워크래프트의 유료 서비스를 광고한다면 주의하세요. 이들 사이트에는 계정 도용을 유발하는 악성 소프트웨어가 설치되어 있을 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Méfiez-vous des sites non officiels proposant des services payants sur World of Warcraft. Ces sites peuvent contenir des logiciels malveillants entraînant le vol de votre compte.', `name_dede` = '|cffffd100Tipp:|r Begegnen Sie inoffiziellen "World of Warcraft"-Webseiten, die kostenpflichtige Serviceleistungen anbieten, mit Vorsicht. Sie können bösartige Software enthalten, die zum Account-Diebstahl führen kann.', `name_zhcn` = '|cffffd100小窍门：|r一定要警惕非官方网站为魔兽世界提供的收费服务。这些广告中很可能包含带有盗号功能的恶意软件。', `name_zhtw` = '|cffffd100Tip:|r請慎防非官方網站的魔獸世界付費服務廣告。這些服務可能含有帳號盜用的惡意程式。', `name_eses` = '|cffffd100Consejo:|r No te fíes de los sitios no oficiales que anuncian servicios de pago de World of Warcraft, ya que podrían contener software malicioso que podría dar lugar al robo de tu cuenta.', `name_esmx` = '|cffffd100Consejo:|r No te fíes de los sitios no oficiales que anuncian servicios de pago de World of Warcraft, ya que podrían contener software malicioso que podría dar lugar al robo de tu cuenta.', `name_ruru` = '|cffffd100Совет:|r Остерегайтесь неофициальных сайтов, предлагающих платные услуги, связанные с World of Warcraft. Такие сайты могут распространять вредоносные программы, способствующие кражам учетных записей.' WHERE `id` = 506;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 계정 도용을 방지하려면 백그라운드에서 스크립트가 실행될 수 있는 브라우저 추가 기능이나 부가 기능을 사용하지 않는 것이 좋습니다.', `name_frfr` = '|cffffd100Astuce :|r Pour éviter qu\'on vous vole votre compte, n\'utilisez pas d\'add-ons ou de fonctionnalités sur votre navigateur qui utilisent des scripts en tâche de fond.', `name_dede` = '|cffffd100Tipp:|r Um Account-Diebstahl zu vermeiden, benutzen Sie keine AddOns oder Features für Browser, die das Ausführen von Scripts im Hintergrund ermöglichen.', `name_zhcn` = '|cffffd100小窍门：|r为了避免帐号被盗，请不要使用允许后台运行脚本的浏览器插件和浏览器功能。', `name_zhtw` = '|cffffd100Tip:|r為防止帳號盜用，請勿使用允許指令碼在背景作業的瀏覽器附加元件或額外功能。', `name_eses` = '|cffffd100Consejo:|r Para evitar el robo de tu cuenta, no utilices addons de navegación que permitan ejecutar scripts en segundo plano.', `name_esmx` = '|cffffd100Consejo:|r Para evitar el robo de tu cuenta, no utilices addons de navegación que permitan ejecutar scripts en segundo plano.', `name_ruru` = '|cffffd100Совет:|r Чтобы избежать кражи учетной записи, не используйте дополнения для браузеров, которые позволяют запуск скриптов в фоновом режиме.' WHERE `id` = 507;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 지도를 열면 퀘스트 수행 장소와 퀘스트 NPC를 볼 수 있습니다.', `name_frfr` = '|cffffd100Astuce :|r Les lieux de quêtes et les donneurs de quêtes sont visibles sur votre carte.', `name_dede` = '|cffffd100Tipp:|r Questziele und Questgeber werden auf der Karte dargestellt.', `name_zhcn` = '|cffffd100小窍门：|r 你可以在地图上看到任务地点和任务给予者。', `name_zhtw` = '|cffffd100小提示:|r你可以在地圖上看到任務地點與任務給予者。', `name_eses` = '|cffffd100Consejo:|r El mapa muestra la ubicación de las misiones y de los personajes que entregan misiones.', `name_esmx` = '|cffffd100Consejo:|r El mapa muestra la ubicación de las misiones y de los personajes que entregan misiones.', `name_ruru` = '|cffffd100Совет:|r Местонахождение заданий и персонажей, дающих их, отмечены на карте.' WHERE `id` = 508;
UPDATE `gametips` SET `name_kokr` = '|cffffd100오늘의 팁:|r 던전 찾기를 이용하여 무작위 던전을 완료하면 보상을 획득할 수 있습니다. 친구들과 던전을 즐기거나 파티를 구할 때 던전 찾기를 이용해 보세요.', `name_frfr` = '|cffffd100Astuce :|r Vous pouvez obtenir des récompenses lorsque vous terminez des donjons aléatoires en utilisant l\'outil Donjons. Vous pouvez vous associer avec des amis ou utiliser l\'outil Donjons pour trouver un groupe.', `name_dede` = '|cffffd100Tipp:|r Ihr könnt Euch Belohnungen verdienen, indem Ihr mittels des Dungeonbrowsers zufällige Dungeons abschließt. Ihr könnt mit einer Gruppe von Freunden gemeinsam gehen oder den Browser verwenden, um eine Dungeongruppe zu finden.', `name_zhcn` = '|cffffd100小窍门：|r使用寻求组队界面进入随机地下城探险可以获得奖励。你可以和好友一道，或利用寻求组队界面来加入地下城探险的队伍。', `name_zhtw` = '|cffffd100小提示:|r使用地城搜尋器來隨機進行地城冒險，可以讓你獲得獎勵。你可以跟朋友組隊或使用地城搜尋器來組成一個地城隊伍。', `name_eses` = '|cffffd100Consejo:|r Puedes obtener recompensas por hacer mazmorras aleatorias usando la herramienta buscador de mazmorras. Puedes ir con un grupo de amigos o usar el buscador de mazmorras para encontrar un grupo de mazmorras.', `name_esmx` = '|cffffd100Consejo:|r Puedes obtener recompensas por hacer mazmorras aleatorias usando la herramienta buscador de mazmorras. Puedes ir con un grupo de amigos o usar el buscador de mazmorras para encontrar un grupo de mazmorras.', `name_ruru` = '|cffffd100Совет:|r Вы можете заработать награды за прохождение случайных подземелий, найденных с помощью системы поиска подземелий. Проходить их можно вместе с друзьями или в группе, собранной с помощью поиска подземелий.' WHERE `id` = 509;
